"Pliki 3MF zawierają rozmieszczone części (w orientacji z plików STL). Otwórz w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory tam, gdzie lista każe („Turn On Supports”).": "The 3MF files contain arranged parts (in the orientation of the STL files). Open them in Bambu Studio / OrcaSlicer / PrusaSlicer, choose the profile and filament, and enable supports where the list says so (“Turn On Supports”).",
