"Podstawa głębokości 6 i 7 ma ok. 280–325 mm długości; USSA daje ją w całości (Whole) albo w 2 częściach (Part 1 + Part 2) dla mniejszych drukarek. Dostępne po zaznaczeniu podstawy przy głębokości 6 lub 7.": "The base for depths 6 and 7 is about 280–325 mm long; USSA provides it whole (Whole) or in 2 parts (Part 1 + Part 2) for smaller printers. Available when the base is selected at depth 6 or 7.",
"Wersja programu: {v}": "Program version: {v}",
"Pliki STL systemu VAULT": "VAULT STL files",
"Konfigurator potrzebuje folderu z plikami VAULT od USSA Design (podfoldery 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Wskaż go – program zapamięta ścieżkę i odczyta listę plików.": "The configurator needs the folder with the VAULT files from USSA Design (subfolders 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Point to it – the program remembers the path and reads the file list.",
"Znaleziono bibliotekę – kliknij „Sprawdź i skanuj” (za pierwszym razem ok. 2–3 minut).": "Library found – click “Check and scan” (about 2–3 minutes the first time).",
