"VAULT to system pojemników firmy USSA Design. Ten program jest nieoficjalnym narzędziem i nie zawiera plików STL – kupisz je u producenta:": "VAULT is a storage system by USSA Design. This program is an unofficial tool and does not include the STL files – buy them from the maker:",
