". Wszystkie płyty trafią do jednego projektu {slicer} z profilami systemowymi: {printer}, {process}, {filament} (części z TPU – osobny projekt).": ". All plates go into one {slicer} project with system profiles: {printer}, {process}, {filament} (TPU parts – a separate project).",
