"Części w różnych kolorach trafiają na osobne płyty, a kolor jest w nazwie płyty. Projekt Bambu Studio ma je jako kolejne filamenty, w innych slicerach każdy kolor to osobny projekt. Bez wybranych kolorów wszystko jak dotąd.": "Parts in different colours go onto separate plates, with the colour in the plate name. A Bambu Studio project has them as separate filaments; in other slicers each colour is a separate project. Without chosen colours everything works as before.",
