"Nowe narzędzie: naprawa siatek STL": "New tool: STL mesh repair",
"Bambu Studio proponuje naprawę plików VAULT przy każdym wczytaniu. napraw_stl.bat w folderze programu naprawia całą bibliotekę za jednym razem tą samą usługą Windows i zapisuje jej naprawioną kopię, którą wskazujesz potem jako bibliotekę.": "Bambu Studio offers to repair the VAULT files every time they are loaded. repair_stl.bat in the program folder repairs the whole library in one go with the same Windows service and writes a repaired copy, which you then select as the library.",
"Opis i narzędzie na GitHubie": "Description and tool on GitHub",
