"po 1 w każdej szczelinie ściany modułu: 2 na każde F (L² i XL² – 3)": "1 in each slot of the module walls: 2 per F (L² and XL² – 3)",
"Skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu: warstwa wyżej jest spięta zatrzaskami z wiekiem i z modułem obok, więc trzeba najpierw zdjąć całą górę wieży. Skrzynka na całą szerokość otwiera się razem z górą (wieko odchyla się z warstwami nad nim).": "A half-width sustainer under another layer won't open in place: the layer above is latched to its lid and to the module next to it, so you have to take off the whole upper part of the tower first. A full-width sustainer opens together with the upper part (the lid tilts back with the layers on it).",
