"ZIP zawiera każdy rodzaj pojemnika raz i listę ilości. Pojemniki trafiają też na listę części, do szacunku i na płyty 3MF w „Przygotuj wydruk”, a w widoku 3D stoją w wysuniętej szufladzie. Wymiary wg standardu gridfinity – pasują też do innych płyt i pojemników gridfinity.": "The ZIP has each kind of bin once and a list of quantities. The bins also go to the parts list, the estimate and the 3MF plates in “Prepare print”, and the 3D view shows them in the opened drawer. Dimensions follow the gridfinity standard – they also fit other gridfinity baseplates and bins.",
