"Moduły, fronty, zamki, pudełka, dachy, podstawa, stopki, koła, kręgosłup, pegboard i uchwyty z plików STL (uproszczone; pierwsze otwarcie trwa dłużej); złożone – moduły zapięte jak w rzeczywistości, rączka wsunięta.": "Modules, facades, locks, boxes, roofs, base, feet, wheels, backbone, pegboard and handles from the STL files (simplified; the first opening takes longer); assembled – modules latched as in reality, handle retracted.",
