"Serwer działa ze starszym generatorem pojemników (płyty i lekkie dno wyszłyby źle) – zamknij jego okno i uruchom konfigurator ponownie.": "The server runs an older bin generator (baseplates and the light floor would come out wrong) – close its window and start the configurator again.",
