"Widok jak we froncie. Wysokość liter: {h} mm. Napis {z} mm nad etykietą – w projekcie Bambu Studio filament zmienia się sam na warstwie od {t} mm (kolor napisu, gdy inny niż kolor etykiety); w innym slicerze zmień go ręcznie.": "View as in the facade. Letter height: {h} mm. Text {z} mm above the label – in a Bambu Studio project the filament changes by itself at the layer from {t} mm (text colour, if different from the label colour); in another slicer change it manually.",
