"na listę części – zamiast tylu samo pustych etykiet": "in the parts list – instead of as many blank labels",
"Etykieta to plik USSA z Twojej biblioteki (Label albo Label for Sustainers) z wypukłym napisem i symbolem. 3MF: wszystkie etykiety ułożone na płytach drukarki z „Przygotuj wydruk”. Drukuj licem do góry; drugi kolor – zmiana filamentu na wysokości wierzchu etykiety.": "The label is the USSA file from your library (Label or Label for Sustainers) with raised text and a symbol. 3MF: all labels arranged on the plates of the printer from “Prepare print”. Print face up; second colour – filament change at the height of the label's top.",
