"Widok jak we froncie. Wysokość liter: {h} mm. Dwie części: lico z wyciętym napisem i litery ({z} mm) równo z licem, licem do stołu. W 3MF etykieta to jeden obiekt z dwóch części; w projekcie Bambu Studio litery mają własny filament w kolorze napisu. Pliki STL – dwa na etykietę.": "Seen as on the front. Letter height: {h} mm. Two parts: the face with the text cut out and the letters ({z} mm) flush with it, face down. In the 3MF the label is one object of two parts; in a Bambu Studio project the letters have their own filament in the text colour. STL files – two per label.",
