"Własne pojemniki gridfinity do szuflad i skrzynek (opcjonalnie)": "Custom gridfinity bins for drawers and sustainers (optional)",
"Etykiety frontów z napisem i symbolem (opcjonalnie)": "Facade labels with text and a symbol (optional)",
"Kopie plików STL i gotowe płyty 3MF dla Twojej drukarki": "STL copies and ready 3MF plates for your printer",
"Następny krok:": "Next step:",
"Zwykły – kluczyk z płetwą i nakładką; ukryty – płaski, równy z frontem, z wyjmowanym kluczem.": "Normal – key with a fin and a cap; hidden – flat, nearly flush with the facade, with a removable key.",
"Listwy zębate łączą prowadnice po obu stronach, żeby szuflada nie przekrzywiała się przy wysuwaniu. Zalecane, gdy w module jest kilka szuflad.": "Geared rails link the runners on both sides so the drawer does not skew when pulled out. Recommended when a module has several drawers.",
"Ile takich samych wież budujesz – lista części mnoży wszystko przez tę liczbę.": "How many identical towers you build – the parts list multiplies everything by this number.",
"Głębokość wszystkich modułów wieży w kratkach gridfinity po 42 mm. Moduł jest o 20 mm dłuższy (np. 4 → 188 mm).": "Depth of all modules in the tower, in 42 mm gridfinity units. The module is 20 mm longer (e.g. 4 → 188 mm).",
"Wieża rośnie od spodu. Warstwa to jeden poziom: moduł z szufladami albo skrzynka z wiekiem. Wysokość 1F to 48 mm, 2F i 4F – dwa i cztery razy więcej.": "The tower grows from the bottom. A layer is one level: a drawer module or a sustainer with a lid. Height 1F is 48 mm, 2F and 4F are two and four times that.",
"Podział wysokiego modułu na szuflady – np. 1F / 1F to dwie niskie szuflady w jednym module 2F.": "How a tall module is split into drawers – e.g. 1F / 1F means two low drawers in one 2F module.",
"Płaskie – gładkie ściany; pod przegródki – rowki na przegródki poprzeczne i podłużne; szczelne – ścianki dzielące skrzynkę na komory.": "Flat – smooth walls; dividers – grooves for cross and lengthwise dividers; sealed – walls splitting the sustainer into compartments.",
"Grid – kratki gridfinity na wierzchu, Table – płaski blat, Bowl – misa na drobiazgi, Under Table Mount – mocowanie pod blatem, Heavyweight – wzmocniony, z rączką (tylko L i XL).": "Grid – gridfinity grid on top, Table – flat top, Bowl – tray for small items, Under Table Mount – mounts under a desk, Heavyweight – reinforced, with a handle (L and XL only).",
"Podstawa pod wieżę z prętem M16 – do niej montuje się koła i stopkę.": "Base under the tower with an M16 rod – wheels and feet are mounted to it.",
"Listwa z tyłu każdej warstwy, która usztywnia wieżę. Przykręca się do niej pegboard i uchwyt wysuwany. Dedykowany – na szerokość wieży, uniwersalny – dwa klocki przy bokach.": "A bar on the back of each layer that stiffens the tower. The pegboard and the pull-out handle attach to it. Dedicated – full tower width, universal – two blocks at the sides.",
"Uchwyt stały – na tyle wieży; wysuwany – rączka na prętach M16 przez kręgosłup (jak w walizce); ścienne – do zawieszenia warstw na ścianie.": "Stationary handle – on the back of the tower; pull-out – a handle on M16 rods through the backbone (like a suitcase); wall mounts – to hang layers on a wall.",
"Pierwszy raz tutaj?": "First time here?",
"Kreator poprowadzi Cię przez 5 kroków: szablon, rozmiar, warstwy od spodu, dach i dodatki – z podglądem i szacunkiem druku. Możesz też od razu edytować „{name}” poniżej.": "The wizard guides you through 5 steps: template, size, layers from the bottom, roof and extras – with a preview and a print estimate. You can also edit “{name}” below right away.",
