"Żadna szuflada ani skrzynka w projekcie nie ma jeszcze wkładu gridfinity. Ustaw „Wkład” w szufladzie albo „wkład gridfinity” w skrzynce (edytor zestawu) – każda z nich dostanie tu własny układ pojemników. Poniżej możesz też zaprojektować układ dla szuflady spoza projektu.": "No drawer or sustainer in the project has a gridfinity insert yet. Set “Insert” on a drawer or “gridfinity insert” on a sustainer (set editor) – each of them gets its own bin layout here. Below you can also design a layout for a drawer outside the project.",
