"Lewy przycisk – obrót, prawy – przesuwanie, kółko – przybliżenie, dwuklik – widok domyślny, kliknięcie frontu – otwarcie szuflady albo skrzynki. Suwak „Rozsunięcie” rozkłada wieżę na części.": "Left button – rotate, right – pan, wheel – zoom, double-click – default view, clicking a facade – opens the drawer or sustainer. The “Explode” slider spreads the tower into parts.",
"Projekt zapisuje się sam w tej przeglądarce. „Projekt → Zapisz projekt” zapisuje go do pliku – na kopię albo do przeniesienia na inny komputer. Instrukcje montażu USSA (PDF) są w Ustawieniach, a przy częściach na liście – odnośniki do właściwych stron.": "The project saves itself in this browser. “Project → Save project” writes it to a file – as a backup or to move it to another computer. The USSA assembly manuals (PDF) are in Settings, and parts in the list link to the right pages.",
