"Płyta gridfinity na dnie pudełka – na niej stoją pojemniki gridfinity (zakładka „Pojemniki gridfinity”); albo przegródki Grid Dividers wsuwane w otwory dna (zakładka „Przegródki”).": "Gridfinity baseplate on the drawer box floor – gridfinity bins stand on it (“Gridfinity bins” tab); or Grid Dividers pushed into the floor holes (“Dividers” tab).",
