"Obróć": "Rotate",
"Zaznaczony łuk: przeciągnij, żeby przesunąć, albo strzałki – o jeden otwór.": "Selected arc: drag to move it, or use the arrow keys – one hole at a time.",
"Przeciągnij wzdłuż rzędu albo kolumny otworów, żeby wstawić przegródkę; poza ostatni otwór – do ścianki. Kliknij przegródkę, żeby ją zaznaczyć (Delete – usuń, Esc – odznacz). Połączenia przegródek (T, narożnik, skrzyżowanie) dostają łączniki: trójnik, kątownik, krzyżak.": "Drag along a row or column of holes to add a divider; past the last hole – up to the wall. Click a divider to select it (Delete – remove, Esc – deselect). Divider joints (T, corner, crossing) get connectors: T-piece, corner piece, “+” piece.",
