"Łuki, łączniki, krótkie przegródki i części brzegowe na wymiar generuje serwer konfiguratora (biblioteka manifold3d, wersja generatora 26) – uruchom konfigurator ponownie po aktualizacji.": "Arcs, connectors, short dividers and made-to-measure edge pieces are generated by the configurator server (manifold3d library, generator version 26) – restart the configurator after updating.",
"część brzegowa na wymiar {l} mm ({h} mm)": "made-to-measure edge piece {l} mm ({h} mm)",
"Części brzegowe:": "Edge pieces:",
"Na wymiar – generuje konfigurator: blok od końca przegródki do ścianki, bez szczeliny. USSA – Straight Edge Piece z blokiem 8 mm (przy ściankach S/M zostaje odsłonięty język).": "Made to measure – generated by the configurator: a block from the divider end to the wall, no gap. USSA – Straight Edge Piece with an 8 mm block (at S/M walls part of the tongue stays exposed).",
"na wymiar": "made to measure",
"Piny wciska się w otwory dna i w spód przegródki. Własne – kształt jak USSA, ale po stronie przegródki cieńsze o wybrany luz (pasują też do przegródek USSA; piny USSA mają tam Ø 4,0 – tyle co gniazdo). Ciasne i luźne USSA różnią się tylko końcem w dnie.": "Pins go into the floor holes and the underside of the divider. Custom – USSA shape, but thinner on the divider side by the chosen clearance (they also fit USSA dividers; USSA pins are Ø 4.0 there – the same as the socket). USSA tight and loose differ only in the floor end.",
"własne z luzem": "custom with clearance",
