"logo na wszystkich frontach szuflad i skrzynek w projekcie": "logo on every drawer and sustainer facade in the project",
"napis (i symbol)": "text (and symbol)",
"ikona": "icon",
"własny plik SVG": "own SVG file",
"np. VAULT – | dzieli na linie": "e.g. VAULT – | splits lines",
"Plik SVG jest za duży (najwyżej {n} KB).": "The SVG file is too large (at most {n} KB).",
"plik SVG": "SVG file",
"Brane są wypełnione kształty (ścieżki, prostokąty, koła…), kolory pomijane – każdy wypełniony kształt to logo. Same linie bez wypełnienia nie dają kształtu.": "Filled shapes are used (paths, rectangles, circles…), colours are ignored – every filled shape is part of the logo. Strokes without fill give no shape.",
"styl": "style",
"wpuszczony – drugi filament równo z licem (AMS)": "inlaid – second filament flush with the face (AMS)",
"wypukły – nad licem, zmiana filamentu pauzą": "raised – above the face, filament change by pause",
"wklęsły – wycięty w licu, jeden kolor": "engraved – cut into the face, one colour",
"wysokość": "height",
"głębokość": "depth",
"kolor logo (= kolor napisów)": "logo colour (= text colour)",
"W projekcie nie ma frontów szuflad ani skrzynek.": "The project has no drawer or sustainer facades.",
"Wpisz napis albo wybierz ikonę lub plik SVG.": "Type a text or pick an icon or SVG file.",
"Liczę miejsce na frontach projektu…": "Calculating the space on the project's facades…",
"To logo nie mieści się na frontach projektu.": "This logo does not fit on the project's facades.",
"Logo {w} × {h} mm na każdym z {n} rodzajów frontów – prawy dolny róg: środek {x} mm od prawej krawędzi i {y} mm od dołu. To największy rozmiar, jaki mieści się na wszystkich frontach projektu – bez frontów S może być większe.": "Logo {w} × {h} mm on each of the {n} facade types – bottom-right corner: centre {x} mm from the right edge and {y} mm from the bottom. This is the largest size that fits on every facade in the project – without S facades it can be larger.",
"STL pierwszego frontu z logo": "STL of the first facade with logo",
"Na liście części fronty USSA zastępują fronty z logo (generuje je konfigurator z plików Twojej biblioteki). Front drukuje się licem do góry, więc logo jest w ostatnich warstwach: wypukłe – zmiana filamentu na wysokości lica, wpuszczone – dwa kolory w ostatnich warstwach (projekt Bambu Studio: logo ma własny filament).": "In the parts list the USSA facades are replaced by facades with the logo (generated by the configurator from your library files). A facade prints face up, so the logo is in the last layers: raised – filament change at the face height, inlaid – two colours in the last layers (Bambu Studio project: the logo has its own filament).",
"jak pojemniki gridfinity": "same as gridfinity bins",
"przegródki szuflad Grid Dividers": "drawer Grid Dividers",
"wkłady gridfinity szuflad": "drawer gridfinity inserts",
"za blisko łącznika – jego ramię ma półtora odstępu (między łącznikami najmniej 4 otwory)": "too close to a connector – its arm is one and a half pitches long (at least 4 holes between connectors)",
"Np. podpory ręczne (Manual Supports), zapasowe części.": "E.g. manual supports, spare parts.",
"Naprawiam fronty z błędami siatki z Twojej biblioteki ({pliki}) – tylko za pierwszym razem: kilka sekund, szuflada S1F do kilkunastu minut…": "Repairing fronts with mesh errors from your library ({pliki}) – only the first time: a few seconds, the S1F drawer up to 15 minutes…",
"Fronty z błędami siatki, których nie udało się naprawić: {pliki}. Użyj naprawionej biblioteki (napraw_stl).": "Fronts with mesh errors that could not be repaired: {pliki}. Use a repaired library (repair_stl).",
"Front {plik}: naprawa siatki nie udała się – {blad}": "Front {plik}: mesh repair failed – {blad}",
"Kręgosłup tylko na warstwach szuflad pod pierwszą skrzynką – zawiasy skrzynki wystają za moduł, a wieko odchyla się do tyłu razem z górą wieży.": "Backbone only on the drawer layers below the first sustainer – the sustainer's hinges stick out behind the module, and its lid tilts back together with the top of the tower.",
"Kręgosłup nie mieści się przy skrzynce na spodzie wieży – zawiasy skrzynki wystają za moduł; jest pomijany.": "The backbone does not fit with a sustainer at the bottom of the tower – the sustainer's hinges stick out behind the module; it is skipped.",
"Pręty uchwytu wysuwanego idą przez całą wysokość wieży – przy skrzynce przeszkadzają zawiasom i wieku; tylko w wieży bez skrzynek.": "The pull-out handle's rods run the full height of the tower – with a sustainer they get in the way of its hinges and lid; only in a tower without sustainers.",
"Uchwyt ścienny tylko w wieży bez skrzynek – zawiasy skrzynki wchodzą w płytę uchwytu, a wieko nie otworzy się przy ścianie.": "Wall mounts only in a tower without sustainers – the sustainer's hinges run into the mount plate, and the lid will not open against the wall.",
"„{name}”: uchwyt ścienny tylko w wieży bez skrzynek – zawiasy skrzynki wchodzą w płytę uchwytu; jest pomijany.": "“{name}”: wall mounts only in a tower without sustainers – the sustainer's hinges run into the mount plate; they are skipped.",
"„{name}”: uchwyt wysuwany tylko w wieży bez skrzynek – pręty przez całą wysokość przeszkadzają zawiasom; jest pomijany.": "“{name}”: the pull-out handle only in a tower without sustainers – its full-height rods get in the way of the hinges; it is skipped.",
"„{name}”: kręgosłup tylko na warstwach szuflad pod pierwszą skrzynką – wyżej jest pomijany.": "“{name}”: backbone only on the drawer layers below the first sustainer – higher up it is skipped.",
"„{name}”: kręgosłup nie mieści się przy skrzynce na spodzie wieży – jest pomijany razem z pegboardem i uchwytem stałym.": "“{name}”: the backbone does not fit with a sustainer at the bottom of the tower – it is skipped together with the pegboard and the stationary handle.",
"W wersji online ta funkcja nie działa – potrzebuje plików VAULT na Twoim komputerze. Pobierz konfigurator (Windows, macOS, Linux):": "This feature does not work in the online version – it needs the VAULT files on your computer. Download the configurator (Windows, macOS, Linux):",
"Pobierz konfigurator": "Download the configurator",
"Wersja online – podgląd": "Online version – preview",
"Planowanie wieży, listy części i śrub, szacunek druku, kreator, przegródki i składanie działają tutaj, a projekt zapisuje się w tej przeglądarce. Kształty z plików STL, pojemniki gridfinity, etykiety z napisem, logo i płyty 3MF działają w programie do pobrania – potrzebują Twoich plików VAULT.": "Planning a tower, parts and hardware lists, print estimates, the wizard, dividers and assembly work here, and the project is saved in this browser. Shapes from the STL files, gridfinity bins, labels with text, the logo and 3MF plates work in the downloadable program – they need your VAULT files.",
