"Serwer działa na starszej wersji programu (inne obszary drukarek). Zamknij okno konsoli serwera, uruchom ponownie konfigurator (uruchom.bat lub run.sh) i odśwież tę stronę.": "Der Server läuft eine ältere Programmversion (andere Druckerbereiche). Schließe das Server-Konsolenfenster, starte den Konfigurator neu (uruchom.bat oder run.sh) und lade diese Seite neu.",
"Sprawdzam serwer…": "Server wird geprüft…",
"Konfigurator nie jest uruchomiony przez serwer, więc przeglądarka nie ma dostępu do plików.": "Der Konfigurator läuft nicht über den Server, daher hat der Browser keinen Zugriff auf die Dateien.",
"Zamknij tę kartę i uruchom uruchom.bat (Windows) albo run.sh (macOS, Linux) w folderze konfigurator (otworzy konfigurator z obsługą plików). Projekt zapisuje się w przeglądarce osobno dla każdego adresu – przenieś go przyciskami Zapisz/Wczytaj projekt.": "Schließe diesen Tab und führe uruchom.bat (Windows) oder run.sh (macOS, Linux) im Ordner konfigurator aus (öffnet den Konfigurator mit Datei-Zugriff). Das Projekt wird im Browser separat für jede Adresse gespeichert – verschiebe es mit den Buttons Projekt speichern/laden.",
"Możesz też pobrać zlecenie i uruchomić je ręcznie:": "Du kannst den Auftrag auch herunterladen und manuell ausführen:",
