"Otwórz plik 3MF w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory dla części „Turn On Supports”. Części są w orientacji z plików STL.": "Öffne die 3MF-Datei in Bambu Studio / OrcaSlicer / PrusaSlicer, wähle Profil und Filament und aktiviere Stützen für die Teile „Turn On Supports”. Die Teile behalten die Orientierung aus den STL-Dateien.",
