"To nie jest plik projektu konfiguratora.": "Das ist keine Konfigurator-Projektdatei.",
"Brak listy plików – ustaw katalog biblioteki w Ustawieniach → „Biblioteka plików” (uruchom.bat lub run.sh) albo uruchom: python skanuj.py \"D:\\ścieżka\\vault\"": "Keine Dateiliste – setze den Bibliotheksordner unter Einstellungen → „Dateibibliothek” (uruchom.bat oder run.sh) oder führe aus: python skanuj.py \"D:\\pfad\\vault\"",
