"Wariant jednej dyszy: część elementów trafi w pas, do którego sięga tylko lewa dysza. Po otwarciu 3MF przypisz filament do lewej dyszy, inaczej pojawi się błąd „Pozycja lub rozmiar…”.": "Eindüsen-Variante: Einige Teile kommen in den Streifen, den nur die linke Düse erreicht. Weise dem 3MF das Filament der linken Düse zu, sonst tritt der Fehler „Position oder Größe…” auf.",
"Wariant jednej dyszy: część elementów trafi w pas, do którego sięga tylko prawa dysza. Po otwarciu 3MF przypisz filament do prawej dyszy, inaczej pojawi się błąd „Pozycja lub rozmiar…”.": "Eindüsen-Variante: Einige Teile kommen in den Streifen, den nur die rechte Düse erreicht. Weise dem 3MF das Filament der rechten Düse zu, sonst tritt der Fehler „Position oder Größe…” auf.",
