"Obszar 325×300 to zasięg jednej dyszy – szeroka płyta może po imporcie zachodzić na pas jednej dyszy; wtedy przesuń całą grupę w bok o kilkanaście mm albo przypisz filament do odpowiedniej dyszy.": "Der Bereich 325×300 ist die Reichweite einer Düse – eine breite Platte kann nach dem Import in den Streifen einer Einzeldüse ragen; schiebe dann die ganze Gruppe seitlich um ein paarzehn mm oder weise das Filament der passenden Düse zu.",
