"plyta": "Platte",
"Pliki 3MF zawierają rozmieszczone części (w orientacji z plików STL). Otwórz w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory tam, gdzie lista każe („Turn On Supports”).": "Die 3MF-Dateien enthalten angeordnete Teile (in der Orientierung aus den STL-Dateien). Öffne sie in Bambu Studio / OrcaSlicer / PrusaSlicer, wähle Profil und Filament und aktiviere Stützen, wo die Liste es sagt („Turn On Supports”).",
