"Podstawa głębokości 6 i 7 ma ok. 280–325 mm długości; USSA daje ją w całości (Whole) albo w 2 częściach (Part 1 + Part 2) dla mniejszych drukarek. Dostępne po zaznaczeniu podstawy przy głębokości 6 lub 7.": "Die Basis für Tiefen 6 und 7 ist ca. 280–325 mm lang; USSA liefert sie ganz (Whole) oder in 2 Teilen (Part 1 + Part 2) für kleinere Drucker. Verfügbar, wenn die Basis bei Tiefe 6 oder 7 ausgewählt ist.",
"Wersja programu: {v}": "Programmversion: {v}",
"Pliki STL systemu VAULT": "VAULT STL-Dateien",
"Konfigurator potrzebuje folderu z plikami VAULT od USSA Design (podfoldery 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Wskaż go – program zapamięta ścieżkę i odczyta listę plików.": "Der Konfigurator braucht den Ordner mit den VAULT-Dateien von USSA Design (Unterordner 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Weise ihn zu – das Programm merkt sich den Pfad und liest die Dateiliste.",
"Znaleziono bibliotekę – kliknij „Sprawdź i skanuj” (za pierwszym razem ok. 2–3 minut).": "Bibliothek gefunden – klicke auf „Prüfen und scannen” (das erste Mal ca. 2–3 Minuten).",
