"Nie masz plików? Kupisz je na stronie producenta:": "Keine Dateien? Du kaufst sie auf der Herstellerseite:",
"Wskaż folder z plikami STL w oknie konfiguratora. Pliki VAULT sprzedaje USSA Design: {url}": "Weise den STL-Ordner im Konfigurator-Fenster zu. Die VAULT-Dateien verkauft USSA Design: {url}",
"Okno wyboru folderu jest niedostępne (Python bez tkinter) – wpisz ścieżkę ręcznie.": "Das Ordner-Auswahl-Fenster ist nicht verfügbar (Python ohne tkinter) – gib den Pfad manuell ein.",
"Okno wyboru folderu jest już otwarte.": "Das Ordner-Auswahl-Fenster ist bereits geöffnet.",
"Wskaż folder z plikami VAULT (STL)": "Weise den Ordner mit den VAULT-Dateien (STL) zu",
"VAULT to system pojemników firmy USSA Design. Ten program jest nieoficjalnym narzędziem i nie zawiera plików STL – kupisz je u producenta:": "VAULT ist ein Aufbewahrungssystem von USSA Design. Dieses Programm ist ein inoffizielles Werkzeug und enthält keine STL-Dateien – du kaufst sie beim Hersteller:",
