"Aktualizacja: instalator działa w nowym oknie, to okno się zamknie.": "Update: Das Installationsprogramm läuft in einem neuen Fenster, dieses Fenster wird geschlossen.",
"Zaktualizować do wersji {v}? Serwer konfiguratora uruchomi się ponownie, projekt zostaje zapisany w przeglądarce.": "Auf Version {v} aktualisieren? Der Konfigurator-Server startet neu, dein Projekt bleibt im Browser gespeichert.",
"Instalator działa w osobnym oknie konsoli. Ta strona przeładuje się sama, gdy nowa wersja wystartuje.": "Das Installationsprogramm läuft in einem eigenen Konsolenfenster. Diese Seite lädt sich automatisch neu, sobald die neue Version gestartet ist.",
