"Wskaż folder na gotowe wydruki": "Ordner für fertige Drucke wählen",
"Podaj pełną ścieżkę folderu, np. D:\\VAULT\\do_druku.": "Gib den vollständigen Ordnerpfad an, z. B. D:\\VAULT\\do_druku.",
"Folder na wydruki nie może leżeć w bibliotece plików VAULT ({dir}) – skanowanie wzięłoby kopie STL za części.": "Der Ausgabeordner darf nicht in der VAULT-Dateibibliothek liegen ({dir}) – beim Scannen würden die STL-Kopien als Teile gelten.",
"Folder na wydruki nie może leżeć w folderze programu.": "Der Ausgabeordner darf nicht im Programmordner liegen.",
"Nie można utworzyć folderu {dir}: {err}": "Ordner {dir} kann nicht erstellt werden: {err}",
"Uwaga: serwer nasłuchuje na {bind} (VAULT_BIND) i nie ma logowania – udostępniaj go tylko w zaufanej sieci. Dozwolone adresy API: {hosts}": "Achtung: Der Server lauscht auf {bind} (VAULT_BIND) und hat keine Anmeldung – nur in einem vertrauenswürdigen Netz freigeben. Erlaubte API-Adressen: {hosts}",
"Płyty są w projekcie {slicer} (części z TPU w osobnym): {file} (profile systemowe: {printer}, {process}, {filament}).": "Die Platten sind in einem {slicer}-Projekt (TPU-Teile in einem eigenen): {file} (Systemprofile: {printer}, {process}, {filament}).",
". Wszystkie płyty trafią do jednego projektu {slicer} z profilami systemowymi: {printer}, {process}, {filament} (części z TPU – osobny projekt).": ". Alle Platten kommen in ein {slicer}-Projekt mit Systemprofilen: {printer}, {process}, {filament} (TPU-Teile – eigenes Projekt).",
"jeden projekt {slicer} ze wszystkimi płytami (zamiast osobnych plików 3MF)": "ein {slicer}-Projekt mit allen Platten (statt einzelner 3MF-Dateien)",
"Projekt {slicer}: {file}": "{slicer}-Projekt: {file}",
"Otwórz projekt w {slicer} (Plik → Otwórz projekt) – płyty, drukarka, proces i filament są już ustawione. Włącz podpory dla części „Turn On Supports”. Części są w orientacji z plików STL.": "Öffne das Projekt in {slicer} (Datei → Projekt öffnen) – Platten, Drucker, Prozess und Filament sind bereits eingestellt. Aktiviere Stützen für die Teile „Turn On Supports“. Die Teile liegen in der Ausrichtung der STL-Dateien.",
