"Projekt jest dla {slicer}. W innym slicerze (np. OrcaSlicer) wybierz po otwarciu swoją drukarkę z listy albo użyj osobnych plików 3MF.": "Das Projekt ist für {slicer}. In einem anderen Slicer (z. B. OrcaSlicer) wähle nach dem Öffnen deinen Drucker aus der Liste oder nutze die einzelnen 3MF-Dateien.",
"Części w różnych kolorach trafiają na osobne płyty, a kolor jest w nazwie płyty. Projekt Bambu Studio ma je jako kolejne filamenty, w innych slicerach każdy kolor to osobny projekt. Bez wybranych kolorów wszystko jak dotąd.": "Teile in verschiedenen Farben kommen auf eigene Platten, die Farbe steht im Plattennamen. Ein Bambu-Studio-Projekt enthält sie als eigene Filamente, in anderen Slicern ist jede Farbe ein eigenes Projekt. Ohne gewählte Farben bleibt alles wie bisher.",
