"Usuwa wcześniejsze wyniki konfiguratora (foldery ze znacznikiem .vault-wynik); inne pliki zostają.": "Löscht frühere Ergebnisse des Konfigurators (Ordner mit der Markierung .vault-wynik); andere Dateien bleiben.",
