"Wyczyść folder wyników": "Ausgabeordner leeren",
"Nowe narzędzie: naprawa siatek STL": "Neues Werkzeug: STL-Netzreparatur",
"Bambu Studio proponuje naprawę plików VAULT przy każdym wczytaniu. napraw_stl.bat w folderze programu naprawia całą bibliotekę za jednym razem tą samą usługą Windows i zapisuje jej naprawioną kopię, którą wskazujesz potem jako bibliotekę.": "Bambu Studio bietet bei jedem Laden an, die VAULT-Dateien zu reparieren. repair_stl.bat im Programmordner repariert die ganze Bibliothek auf einmal mit demselben Windows-Dienst und schreibt eine reparierte Kopie, die du danach als Bibliothek auswählst.",
