"Skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu: warstwa wyżej jest spięta zatrzaskami z wiekiem i z modułem obok, więc trzeba najpierw zdjąć całą górę wieży. Skrzynka na całą szerokość otwiera się razem z górą (wieko odchyla się z warstwami nad nim).": "Eine Box mit halber Breite unter einer anderen Ebene lässt sich nicht an Ort und Stelle öffnen: Die Ebene darüber ist mit ihrem Deckel und mit dem Nachbarmodul verriegelt, du musst also zuerst den ganzen oberen Teil des Turms abnehmen. Eine Box über die volle Breite öffnet sich zusammen mit dem oberen Teil (der Deckel klappt mit den Ebenen darauf nach hinten).",
