"ZIP zawiera każdy rodzaj pojemnika raz i listę ilości. Pojemniki trafiają też na listę części, do szacunku i na płyty 3MF w „Przygotuj wydruk”, a w widoku 3D stoją w wysuniętej szufladzie. Wymiary wg standardu gridfinity – pasują też do innych płyt i pojemników gridfinity.": "Die ZIP-Datei enthält jede Behälterart einmal und eine Mengenliste. Die Behälter kommen auch in die Teileliste, in die Schätzung und auf die 3MF-Platten unter „Ausdruck vorbereiten“; die 3D-Ansicht zeigt sie in der geöffneten Schublade. Maße nach Gridfinity-Standard – passen auch zu anderen Gridfinity-Platten und -Behältern.",
