"Czerwona ramka: najwyżej {mm} mm nad dnem – pojemnik do {a} jedn. z rantem, {b} bez rantu.": "Roter Rahmen: höchstens {mm} mm über dem Boden – Behälter bis {a} Einheiten mit Stapelrand, {b} ohne.",
"Pegboard przykręca się do kręgosłupa – wybierz kręgosłup.": "Das Pegboard wird an das Rückgrat geschraubt – wähle ein Rückgrat.",
"Moduły, fronty, zamki, pudełka, dachy, podstawa, stopki, koła, kręgosłup, pegboard i uchwyty z plików STL (uproszczone; pierwsze otwarcie trwa dłużej); złożone – moduły zapięte jak w rzeczywistości, rączka wsunięta.": "Module, Fronten, Schlösser, Kästen, Dächer, Sockel, Füße, Räder, Rückgrat, Pegboard und Griffe aus den STL-Dateien (vereinfacht; das erste Öffnen dauert länger); zusammengebaut – Module eingerastet wie in echt, Griff eingeschoben.",
"jedna na otwór w uchwycie (1F – bez otworu)": "eins pro Loch in der Halterung (1F – ohne Loch)",
