"Serwer działa ze starszym generatorem pojemników (płyty i lekkie dno wyszłyby źle) – zamknij jego okno i uruchom konfigurator ponownie.": "Der Server läuft mit einem älteren Behälter-Generator (Grundplatten und leichter Boden kämen falsch heraus) – schließe sein Fenster und starte den Konfigurator neu.",
"{n} pojemników wychodzi poza siatkę albo stoi na zabudowanym polu płyty – przesuń je albo usuń; nie trafią do pliku ZIP ani na listę części.": "{n} Behälter liegen außerhalb des Rasters oder auf dem geschlossenen Feld der Grundplatte – verschiebe oder lösche sie; sie fehlen in der ZIP-Datei und in der Teileliste.",
"Pole zabudowane w płycie USSA (wycięcie na palec) – bez kieszeni.": "Geschlossenes Feld der USSA-Grundplatte (Griffmulde) – ohne Tasche.",
