"Widok jak we froncie. Wysokość liter: {h} mm. Napis {z} mm nad etykietą – w projekcie Bambu Studio filament zmienia się sam na warstwie od {t} mm (kolor napisu, gdy inny niż kolor etykiety); w innym slicerze zmień go ręcznie.": "Ansicht wie in der Front. Buchstabenhöhe: {h} mm. Schrift {z} mm über dem Etikett – im Bambu-Studio-Projekt wechselt das Filament automatisch ab der Schicht bei {t} mm (Schriftfarbe, wenn anders als die Etikettenfarbe); in einem anderen Slicer wechsle es von Hand.",
"etykiety": "etiketten",
"STL tej etykiety": "STL dieses Etiketts",
"na listę części – zamiast tylu samo pustych etykiet": "in der Teileliste – statt ebenso vieler leerer Etiketten",
"Etykieta to plik USSA z Twojej biblioteki (Label albo Label for Sustainers) z wypukłym napisem i symbolem. 3MF: wszystkie etykiety ułożone na płytach drukarki z „Przygotuj wydruk”. Drukuj licem do góry; drugi kolor – zmiana filamentu na wysokości wierzchu etykiety.": "Das Etikett ist die USSA-Datei aus deiner Bibliothek (Label oder Label for Sustainers) mit erhabenem Text und Symbol. 3MF: alle Etiketten auf den Platten des Druckers aus „Ausdruck vorbereiten“. Mit der Sichtseite nach oben drucken; zweite Farbe – Filamentwechsel auf Höhe der Etikettenoberseite.",
"bez symbolu": "kein Symbol",
"szuflada / skrzynka 2F i 4F (Label)": "Schublade / Sustainer 2F und 4F (Label)",
"skrzynka 1F (Label for Sustainers)": "Sustainer 1F (Label for Sustainers)",
"litery niższe niż 3 mm – skróć napis albo podziel go na 2 linie": "Buchstaben niedriger als 3 mm – Text kürzen oder auf 2 Zeilen aufteilen",
"Brak pliku {file} w bibliotece": "Datei {file} fehlt in der Bibliothek",
"{file}: siatka z błędami – napraw bibliotekę (napraw_stl)": "{file}: Netz mit Fehlern – Bibliothek reparieren (repair_stl)",
"styl napisu": "Textstil",
"wypukły – druk licem do góry": "erhaben – mit der Sichtseite nach oben drucken",
"wklęsły – druk licem do stołu": "vertieft – mit der Sichtseite nach unten drucken",
"głębokość napisu": "Texttiefe",
"Widok jak we froncie. Wysokość liter: {h} mm. Napis wycięty na {z} mm w licu; plik leży licem do stołu – gładkie lico i ostre krawędzie liter (jeden kolor).": "Ansicht wie an der Front. Buchstabenhöhe: {h} mm. Text {z} mm in die Sichtseite eingeschnitten; die Datei liegt mit der Sichtseite auf dem Bett – glatte Fläche und scharfe Buchstabenkanten (eine Farbe).",
"puste etykiety (Label) na liście części": "leere Etiketten (Label) in der Teileliste",
"Wyłącz, jeśli etykiet nie drukujesz albo robisz je w zakładce „Etykiety” (te zostają na liście).": "Ausschalten, wenn du keine Etiketten druckst oder sie im Reiter „Etiketten“ erstellst (diese bleiben in der Liste).",
"wpuszczony – drugi filament, druk licem do stołu": "eingelegt – zweites Filament, mit der Sichtseite nach unten drucken",
"grubość napisu": "Textdicke",
"kolor napisu (wspólny dla etykiet)": "Schriftfarbe (für alle Etiketten)",
"Widok jak we froncie. Wysokość liter: {h} mm. Dwie części: lico z wyciętym napisem i litery ({z} mm) równo z licem, licem do stołu. W 3MF etykieta to jeden obiekt z dwóch części; w projekcie Bambu Studio litery mają własny filament w kolorze napisu. Pliki STL – dwa na etykietę.": "Ansicht wie an der Front. Buchstabenhöhe: {h} mm. Zwei Teile: die Sichtseite mit ausgeschnittenem Text und die Buchstaben ({z} mm) bündig damit, Sichtseite nach unten. Im 3MF ist das Etikett ein Objekt aus zwei Teilen; im Bambu-Studio-Projekt haben die Buchstaben ein eigenes Filament in der Textfarbe. STL-Dateien – zwei pro Etikett.",
