"wpuszczony – drugi filament, równo z półką": "eingelegt – zweites Filament, bündig mit der Ablage",
"wklęsły – jeden kolor": "vertieft – eine Farbe",
"kolor napisu (wspólny z etykietami)": "Textfarbe (wie bei den Etiketten)",
"Przegródki od lewej, najpierw przedni rząd.": "Fächer von links, vordere Reihe zuerst.",
"Symbol…": "Symbol…",
"Bez perspektywy": "Ohne Perspektive",
"Rozsunięcie wieży we wszystkich osiach – warstwy w pionie, fronty do przodu, moduły i koła na boki, kręgosłup do tyłu": "Turm in alle Richtungen auseinanderziehen – Ebenen nach oben, Fronten nach vorn, Module und Räder zur Seite, Rückgrat nach hinten",
"Rozsunięcie": "Auseinanderziehen",
"Wczytuję symbole…": "Symbole werden geladen…",
