"Cofnij": "Rückgängig",
"Usunięto warstwę {n}": "Ebene {n} gelöscht",
"Usunięto plik z listy": "Datei aus der Liste entfernt",
"Usunięto „{name}”": "„{name}“ gelöscht",
"Usunięto pojemnik": "Behälter gelöscht",
"Usunięto układ pojemników": "Behälter-Layout gelöscht",
"Usunięto etykietę": "Etikett gelöscht",
"Pliki STL do wydrukowania – ilości, czas, filament, licznik wydrukowanych": "Zu druckende STL-Dateien – Mengen, Zeit, Filament, Zähler der gedruckten Teile",
"Śruby, pręty, magnesy i inne elementy do kupienia": "Schrauben, Stangen, Magnete und andere Kaufteile",
"Własne pojemniki gridfinity do szuflad i skrzynek (opcjonalnie)": "Eigene Gridfinity-Behälter für Schubladen und Sustainer (optional)",
"Etykiety frontów z napisem i symbolem (opcjonalnie)": "Front-Etiketten mit Text und Symbol (optional)",
"Kopie plików STL i gotowe płyty 3MF dla Twojej drukarki": "STL-Kopien und fertige 3MF-Platten für deinen Drucker",
"Następny krok:": "Nächster Schritt:",
"Zwykły – kluczyk z płetwą i nakładką; ukryty – płaski, równy z frontem, z wyjmowanym kluczem.": "Normal – Schlüssel mit Griff und Kappe; versteckt – flach, fast bündig mit der Front, mit abnehmbarem Schlüssel.",
"Listwy zębate łączą prowadnice po obu stronach, żeby szuflada nie przekrzywiała się przy wysuwaniu. Zalecane, gdy w module jest kilka szuflad.": "Zahnleisten verbinden die Führungen beider Seiten, damit die Schublade beim Herausziehen nicht verkantet. Empfohlen, wenn ein Modul mehrere Schubladen hat.",
"Ile takich samych wież budujesz – lista części mnoży wszystko przez tę liczbę.": "Wie viele gleiche Türme du baust – die Teileliste multipliziert alles mit dieser Zahl.",
"Głębokość wszystkich modułów wieży w kratkach gridfinity po 42 mm. Moduł jest o 20 mm dłuższy (np. 4 → 188 mm).": "Tiefe aller Module des Turms in Gridfinity-Rastern zu 42 mm. Das Modul ist 20 mm länger (z. B. 4 → 188 mm).",
"Wieża rośnie od spodu. Warstwa to jeden poziom: moduł z szufladami albo skrzynka z wiekiem. Wysokość 1F to 48 mm, 2F i 4F – dwa i cztery razy więcej.": "Der Turm wächst von unten. Eine Ebene ist eine Stufe: ein Schubladenmodul oder ein Sustainer mit Deckel. Höhe 1F sind 48 mm, 2F und 4F das Zwei- und Vierfache.",
"Podział wysokiego modułu na szuflady – np. 1F / 1F to dwie niskie szuflady w jednym module 2F.": "Aufteilung eines hohen Moduls in Schubladen – z. B. 1F / 1F sind zwei niedrige Schubladen in einem 2F-Modul.",
"Płaskie – gładkie ściany; pod przegródki – rowki na przegródki poprzeczne i podłużne; szczelne – ścianki dzielące skrzynkę na komory.": "Flach – glatte Wände; für Trennwände – Nuten für Quer- und Längstrennwände; dicht – Wände, die den Sustainer in Fächer teilen.",
"Grid – kratki gridfinity na wierzchu, Table – płaski blat, Bowl – misa na drobiazgi, Under Table Mount – mocowanie pod blatem, Heavyweight – wzmocniony, z rączką (tylko L i XL).": "Grid – Gridfinity-Raster oben, Table – flache Platte, Bowl – Schale für Kleinkram, Under Table Mount – Montage unter der Tischplatte, Heavyweight – verstärkt, mit Griff (nur L und XL).",
"Podstawa pod wieżę z prętem M16 – do niej montuje się koła i stopkę.": "Sockel unter dem Turm mit M16-Stange – daran werden Räder und Fuß montiert.",
"Listwa z tyłu każdej warstwy, która usztywnia wieżę. Przykręca się do niej pegboard i uchwyt wysuwany. Dedykowany – na szerokość wieży, uniwersalny – dwa klocki przy bokach.": "Leiste an der Rückseite jeder Ebene, die den Turm versteift. Daran werden Lochwand und ausziehbarer Griff befestigt. Spezifisch – auf Turmbreite, universell – zwei Blöcke an den Seiten.",
"Uchwyt stały – na tyle wieży; wysuwany – rączka na prętach M16 przez kręgosłup (jak w walizce); ścienne – do zawieszenia warstw na ścianie.": "Fester Griff – an der Turmrückseite; ausziehbar – Griff auf M16-Stangen durch das Rückgrat (wie beim Koffer); Wandhalter – zum Aufhängen der Ebenen an der Wand.",
"Pierwszy raz tutaj?": "Zum ersten Mal hier?",
"Kreator poprowadzi Cię przez 5 kroków: szablon, rozmiar, warstwy od spodu, dach i dodatki – z podglądem i szacunkiem druku. Możesz też od razu edytować „{name}” poniżej.": "Der Assistent führt dich in 5 Schritten: Vorlage, Größe, Ebenen von unten, Dach und Extras – mit Vorschau und Druckschätzung. Du kannst „{name}“ auch direkt unten bearbeiten.",
"Kreator wieży…": "Turm-Assistent…",
"Nie pokazuj": "Nicht mehr anzeigen",
"Szablon": "Vorlage",
"Rozmiar": "Größe",
"Warstwy": "Ebenen",
"Góra i dodatki": "Oben und Extras",
"Podsumowanie": "Zusammenfassung",
"Pusta wieża": "Leerer Turm",
"Jedna warstwa szuflad – resztę dodasz sam.": "Eine Schubladenebene – den Rest fügst du selbst hinzu.",
"Biurko": "Schreibtisch",
"Niska wieża M z szufladami i płaskim blatem.": "Ein niedriger M-Turm mit Schubladen und flacher Platte.",
"Warsztat na kółkach": "Werkstatt auf Rädern",
"Wysoka wieża L na kołach, z kręgosłupem, rączką i dachem z kratkami.": "Ein hoher L-Turm auf Rädern, mit Rückgrat, Griff und Rasterdach.",
"Skrzynka narzędziowa": "Werkzeugkiste",
"Szuflady na dole, na górze skrzynka z wiekiem i przegródkami, uchwyt stały.": "Unten Schubladen, oben ein Sustainer mit Deckel und Trennwänden, fester Griff.",
"Pod blat": "Unter der Tischplatte",
"Szuflady przykręcane pod blat biurka (dach Under Table Mount).": "Schubladen unter die Tischplatte geschraubt (Dach Under Table Mount).",
"Od czego zaczynasz?": "Womit fängst du an?",
"Wybierz gotowy pomysł i zmień go w kolejnych krokach – albo zacznij od pustej wieży.": "Wähle eine fertige Idee und passe sie in den nächsten Schritten an – oder starte mit einem leeren Turm.",
"Szerokość wieży": "Turmbreite",
"wąska – pojedyncze szuflady": "schmal – einzelne Schubladen",
"średnia": "mittel",
"szeroka – też 2× S obok siebie": "breit – auch 2× S nebeneinander",
"najszersza – tylko warstwy 1F": "am breitesten – nur 1F-Ebenen",
"Głębokość": "Tiefe",
"Nazwa i ilość": "Name und Menge",
"Warstwy od spodu": "Ebenen von unten",
"Każda warstwa stoi na poprzedniej. Szerokość wieży: {W} – wyżej tylko układy tej szerokości.": "Jede Ebene steht auf der vorherigen. Turmbreite: {W} – darüber nur Anordnungen dieser Breite.",
"Dodaj na górze:": "Oben hinzufügen:",
"szuflady {h}F": "Schubladen {h}F",
"skrzynka {h}F": "Sustainer {h}F",
"Wkłady gridfinity, przegródki skrzynek i podział frontów każdej kolumny ustawisz później w edytorze zestawu.": "Gridfinity-Einsätze, Sustainer-Trennwände und die Frontaufteilung jeder Spalte stellst du später im Set-Editor ein.",
"Po utworzeniu zestaw możesz dalej zmieniać w edytorze: wkłady i pojemniki gridfinity w szufladach, przegródki skrzynek, pegboard. Cofnij (Ctrl+Z) wycofa utworzenie.": "Nach dem Erstellen kannst du das Set im Editor weiter ändern: Gridfinity-Einsätze und Behälter in Schubladen, Sustainer-Trennwände, Lochwand. Rückgängig (Strg+Z) nimmt das Erstellen zurück.",
"Anuluj": "Abbrechen",
