"Dalej": "Weiter",
"Utwórz (zamiast „{name}”)": "Erstellen (statt „{name}“)",
"Utwórz zestaw": "Set erstellen",
"Kreator wieży": "Turm-Assistent",
"Podgląd": "Vorschau",
"Utworzono „{name}”": "„{name}“ erstellt",
"Kreator…": "Assistent…",
"Nowa wieża krok po kroku: szablon, rozmiar, warstwy, góra i dodatki": "Neuer Turm Schritt für Schritt: Vorlage, Größe, Ebenen, Oben und Extras",
"Wyzerowano licznik wydrukowanych części": "Zähler der gedruckten Teile zurückgesetzt",
"Skopiowano pojemniki: {n}": "Behälter kopiert: {n}",
"Usunięto wszystkie pojemniki z układu": "Alle Behälter aus dem Layout entfernt",
"Żadna szuflada ani skrzynka w projekcie nie ma jeszcze wkładu gridfinity. Ustaw „Wkład” w szufladzie albo „wkład gridfinity” w skrzynce (edytor zestawu) – każda z nich dostanie tu własny układ pojemników. Poniżej możesz też zaprojektować układ dla szuflady spoza projektu.": "Noch keine Schublade und kein Sustainer im Projekt hat einen Gridfinity-Einsatz. Stelle „Einsatz“ bei einer Schublade oder „Gridfinity-Einsatz“ bei einem Sustainer ein (Set-Editor) – jede bekommt hier ihr eigenes Behälter-Layout. Unten kannst du auch ein Layout für eine Schublade außerhalb des Projekts entwerfen.",
"Pomoc": "Hilfe",
"Jak pracować z konfiguratorem": "So arbeitest du mit dem Konfigurator",
"wskaż folder z plikami STL od USSA.": "wähle den Ordner mit den STL-Dateien von USSA.",
"Wieża": "Turm",
"kreatorem albo w edytorze zestawu: warstwy od spodu, dach, podstawa i dodatki.": "mit dem Assistenten oder im Set-Editor: Ebenen von unten, Dach, Sockel und Extras.",
"Listy części": "Teilelisten",
"„Do druku” (pliki STL, czas, filament, licznik wydrukowanych) i „Niedrukowane” (śruby, pręty, magnesy).": "„Zum Drucken“ (STL-Dateien, Zeit, Filament, Zähler) und „Hardware“ (Schrauben, Stangen, Magnete).",
"Opcjonalnie": "Optional",
"pojemniki gridfinity do szuflad i skrzynek oraz etykiety frontów z napisem.": "Gridfinity-Behälter für Schubladen und Sustainer sowie Front-Etiketten mit Text.",
"Wydruk": "Druck",
"kopie STL i płyty 3MF albo projekt slicera dla Twojej drukarki.": "STL-Kopien und 3MF-Platten oder ein Slicer-Projekt für deinen Drucker.",
"Skróty klawiszowe": "Tastenkürzel",
"cofnij / ponów zmianę w projekcie (poza polami tekstowymi)": "Projektänderung rückgängig / wiederholen (außerhalb von Textfeldern)",
"usuń zaznaczony pojemnik (zakładka pojemników)": "markierten Behälter löschen (Reiter Behälter)",
"zamknij okno (pomoc, ustawienia, kreator, widok 3D) albo odznacz pojemnik": "Fenster schließen (Hilfe, Einstellungen, Assistent, 3D-Ansicht) oder Behälter abwählen",
"Widok 3D": "3D-Ansicht",
"Lewy przycisk – obrót, prawy – przesuwanie, kółko – przybliżenie, dwuklik – widok domyślny, kliknięcie frontu – otwarcie szuflady albo skrzynki. Suwak „Rozsunięcie” rozkłada wieżę na części.": "Linke Taste – drehen, rechte – verschieben, Mausrad – zoomen, Doppelklick – Standardansicht, Klick auf eine Front – Schublade oder Sustainer öffnen. Der Regler „Auseinanderziehen“ zerlegt den Turm in seine Teile.",
"Projekt zapisuje się sam w tej przeglądarce. „Projekt → Zapisz projekt” zapisuje go do pliku – na kopię albo do przeniesienia na inny komputer. Instrukcje montażu USSA (PDF) są w Ustawieniach, a przy częściach na liście – odnośniki do właściwych stron.": "Das Projekt speichert sich automatisch in diesem Browser. „Projekt → Projekt speichern“ schreibt es in eine Datei – als Sicherung oder zum Übertragen auf einen anderen Computer. Die USSA-Montageanleitungen (PDF) sind in den Einstellungen, die Teile in der Liste verlinken auf die passenden Seiten.",
"„{name}”: uchwyt wysuwany montuje się na kręgosłupie – wybierz kręgosłup.": "„{name}“: Der ausziehbare Griff wird am Rückgrat montiert – wähle ein Rückgrat.",
"„{name}”: koła i stopka montuje się do podstawy – bez niej są pomijane.": "„{name}“: Räder und Fuß werden am Sockel montiert – ohne ihn werden sie ausgelassen.",
"„{name}”: pegboard przykręca się do kręgosłupa – bez niego jest pomijany.": "„{name}“: Die Lochwand wird ans Rückgrat geschraubt – ohne Rückgrat wird sie ausgelassen.",
"„{name}”, warstwa {n}: skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu.": "„{name}“, Ebene {n}: Ein Sustainer halber Breite unter einer anderen Ebene lässt sich nicht an Ort und Stelle öffnen.",
"Pojemniki poza siatką płyty: {n} – nie trafiają na listę części (zakładka „Pojemniki gridfinity”).": "Behälter außerhalb des Plattenrasters: {n} – sie kommen nicht in die Teileliste (Reiter „Gridfinity-Behälter“).",
"Uwagi do projektu: {n}": "Hinweise zum Projekt: {n}",
