"wkład gridfinity we wszystkich szufladach": "Gridfinity-Einsatz in allen Schubladen",
"wkład gridfinity we wszystkich skrzynkach": "Gridfinity-Einsatz in allen Sustainern",
"Etykiety z projektu": "Etiketten aus dem Projekt",
"Po jednej etykiecie na każdy front szuflady i skrzynki w projekcie, z opisem miejsca. Kolejne kliknięcie dopisuje tylko nowe fronty.": "Je ein Etikett für jede Schubladen- und Sustainer-Front im Projekt, mit Angabe der Position. Ein weiterer Klick ergänzt nur neue Fronten.",
"Dodano etykiety z projektu: {n}": "Etiketten aus dem Projekt hinzugefügt: {n}",
"Wszystkie fronty projektu mają już etykiety": "Alle Fronten im Projekt haben bereits Etiketten",
"Puste etykiety USSA są nadal na liście części – fronty, którym nie wpiszesz napisu, dostaną pustą etykietę.": "Leere USSA-Etiketten stehen noch auf der Teileliste – Fronten ohne Text bekommen ein leeres Etikett.",
"Nie drukuj pustych": "Leere nicht drucken",
"Wyłączono puste etykiety na liście części": "Leere Etiketten von der Teileliste entfernt",
"Miejsce: {g}": "Position: {g}",
"Puste etykiety są wyłączone, a liczba etykiet z napisem nie zgadza się z liczbą frontów: {list}.": "Leere Etiketten sind ausgeschaltet, aber die Zahl der Etiketten mit Text passt nicht zur Zahl der Fronten: {list}.",
"Label (szuflady, skrzynki 2F i 4F) {a} z {b}": "Label (Schubladen, Sustainer 2F und 4F) {a} von {b}",
"Label for Sustainers (skrzynki 1F) {a} z {b}": "Label for Sustainers (Sustainer 1F) {a} von {b}",
"Konfigurator VAULT: odmowa dostępu. Adres {host} nie jest dozwolony – dopisz go do zmiennej VAULT_HOSTS (np. VAULT_HOSTS={host}) i uruchom serwer ponownie.": "VAULT-Konfigurator: Zugriff verweigert. Die Adresse {host} ist nicht erlaubt – füge sie zur Variable VAULT_HOSTS hinzu (z. B. VAULT_HOSTS={host}) und starte den Server neu.",
"Za duże zapytanie.": "Anfrage zu groß.",
"Za dużo sztuk w zleceniu (najwyżej {n}).": "Zu viele Teile im Auftrag (höchstens {n}).",
"Starsze wyniki (sprzed wersji 1.1.35) nie mają znacznika, więc zostały – usuń je ręcznie, jeśli nie są potrzebne: {list}": "Ältere Ergebnisse (vor Version 1.1.35) haben keine Markierung und wurden behalten – lösche sie von Hand, wenn du sie nicht brauchst: {list}",
"Folder na wydruki nie może być korzeniem dysku ani folderem domowym – wybierz podfolder, np. {dir}.": "Der Ausgabeordner darf kein Laufwerksstamm und nicht dein Benutzerordner sein – wähle einen Unterordner, z. B. {dir}.",
"wczytywanie kształtu…": "Form wird geladen…",
"brak podglądu kształtu": "keine Formvorschau",
"drukuj klucz (jeden na projekt)": "Schlüssel drucken (einer pro Projekt)",
"Hidden Key Part 2 to wyjmowana rączka do obracania ukrytych zamków – pasuje do wszystkich szuflad, więc wystarczy jedna na projekt.": "Hidden Key Part 2 ist ein abnehmbarer Griff zum Drehen der versteckten Schlösser – er passt in jede Schublade, daher reicht einer pro Projekt.",
"Filament według koloru:": "Filament nach Farbe:",
