"Dach": "Dach",
"Tył wieży: kręgosłup, pegboard, uchwyt ścienny": "Turmhinterseite: Backbone, Pegboard, Wandhalterung",
"Uchwyty": "Griffe",
"Składanie": "Zusammenbau",
"Zrobione kroki: {done} z {n}": "Erledigte Schritte: {done} von {n}",
"Wyczyszczono zaznaczone kroki": "Abgehakte Schritte zurückgesetzt",
"Wyczyść zaznaczenia": "Häkchen entfernen",
"kroki dla jednej wieży, powtórz {n}×": "Schritte für einen Turm, {n}× wiederholen",
"Kroki od spodu wieży: części i elementy niedrukowane na jedną wieżę, przy częściach strony instrukcji USSA (gdy PDF-y są w bibliotece). Zaznaczone kroki zapisują się z projektem.": "Schritte von unten nach oben: Teile und Hardware für einen Turm, bei den Teilen die Seiten der USSA-Anleitung (wenn die PDFs in der Bibliothek sind). Abgehakte Schritte werden mit dem Projekt gespeichert.",
"kroki od spodu wieży z częściami, śrubami i stronami instrukcji USSA.": "Schritte von unten mit Teilen, Schrauben und Seiten der USSA-Anleitung.",
