"_napis": "_Text",
"Uchwyt ścienny przykręca się do tyłu modułów w miejscu kręgosłupa – wybierz kręgosłup „brak”.": "Die Wandhalterung wird an die Rückseite der Module geschraubt, dort wo das Backbone sitzt – stelle das Backbone auf „keines“.",
"„{name}”: uchwyt ścienny przykręca się do tyłu modułów w miejscu kręgosłupa – z kręgosłupem jest pomijany.": "„{name}“: Die Wandhalterung wird an die Rückseite der Module geschraubt, dort wo das Backbone sitzt – mit Backbone wird sie weggelassen.",
"Uchwyt stały przykręca się do kręgosłupa – wybierz kręgosłup.": "Der feste Griff wird an das Backbone geschraubt – wähle ein Backbone.",
"„{name}”: uchwyt stały przykręca się do kręgosłupa – bez niego jest pomijany.": "„{name}“: Der feste Griff wird an das Backbone geschraubt – ohne Backbone wird er weggelassen.",
"kółka meblowe (Casters Mode)": "Möbelrollen (Casters Mode)",
"Kółka meblowe stoją tam, gdzie koła i stopka – zaznacz podstawę i odznacz koła i stopkę.": "Möbelrollen sitzen dort, wo Räder und Fuß sind – wähle die Basis und entferne Räder und Fuß.",
"Kółko meblowe skrętne z trzpieniem gwintowanym M8": "Lenkrolle mit M8-Gewindezapfen",
"kółka meblowe (Casters Mode) – trzpień w otworze Ø 7 mm w spodzie podstawy": "Möbelrollen (Casters Mode) – Zapfen in der Ø 7 mm Bohrung in der Unterseite der Basis",
"„{name}”: kółka meblowe stoją tam, gdzie koła i stopka – przy kołach albo stopce są pomijane.": "„{name}“: Möbelrollen sitzen dort, wo Räder und Fuß sind – mit Rädern oder Fuß werden sie weggelassen.",
"Pojemniki wyższe niż miejsce w szufladzie albo skrzynce: {n} (zakładka „Pojemniki gridfinity”).": "Behälter höher als der Platz in der Schublade oder im Ablagekasten: {n} (Tab „Gridfinity-Behälter“).",
"Etykiety z literami niższymi niż 3 mm: {n} – skróć napis albo podziel go na 2 linie.": "Etiketten mit Buchstaben unter 3 mm: {n} – kürze den Text oder teile ihn auf 2 Zeilen auf.",
