"przegródki Grid Dividers": "Grid Dividers (Trennwände)",
"Płyta gridfinity na dnie pudełka – na niej stoją pojemniki gridfinity (zakładka „Pojemniki gridfinity”); albo przegródki Grid Dividers wsuwane w otwory dna (zakładka „Przegródki”).": "Gridfinity-Grundplatte auf dem Schubladenboden – darauf stehen Gridfinity-Behälter (Reiter „Gridfinity-Behälter“); oder Grid Dividers in den Bodenlöchern (Reiter „Trennwände“).",
"za krótka – najkrótsza przegródka ma {n} odstępów": "zu kurz – die kürzeste Trennwand hat {n} Abstände",
"za długa – najdłuższa przegródka ma {n} odstępów": "zu lang – die längste Trennwand hat {n} Abstände",
"krzyżuje się z inną przegródką": "kreuzt eine andere Trennwand",
"nachodzi na inną przegródkę": "überlappt eine andere Trennwand",
"za blisko równoległej przegródki – stopy nachodzą (odstęp najmniej 3 otwory)": "zu nah an einer parallelen Trennwand – die Füße überlappen (mindestens 3 Löcher Abstand)",
"za blisko ścianki – stopa przegródki na nią wchodzi": "zu nah an der Wand – der Fuß der Trennwand stößt an",
"Zaprojektuj przegródki Grid Dividers dla tej szuflady ({n} szt.)": "Grid Dividers für diese Schublade entwerfen ({n} Stk.)",
"Przegródki Grid Dividers z błędem: {n} – nie trafiają na listę części ({where}).": "Grid Dividers mit Fehler: {n} – nicht in der Teileliste ({where}).",
"Przegródki szuflad (Grid Dividers)": "Schubladen-Trennwände (Grid Dividers)",
"Żadna szuflada nie ma wkładu „przegródki Grid Dividers”. Ustaw go w edytorze zestawu: Wkład → przegródki Grid Dividers.": "Keine Schublade hat den Einsatz „Grid Dividers“. Stelle ihn im Set-Editor ein: Einsatz → Grid Dividers.",
"Przegródki wsuwa się w otwory w dnie pudełka szuflady (co 10,5 mm) – zamiast płyty gridfinity.": "Trennwände werden in die Löcher im Schubladenboden gesteckt (alle 10,5 mm) – statt einer Gridfinity-Grundplatte.",
