"Wysokość:": "Höhe:",
"20 mm – niskie przegródki do każdej szuflady; 34,5 mm – pełna wysokość szuflady 1F; 82,5 mm – pełna wysokość szuflady 2F.": "20 mm – niedrige Trennwände für jede Schublade; 34,5 mm – volle Höhe einer 1F-Schublade; 82,5 mm – volle Höhe einer 2F-Schublade.",
