"Obszar 325×300 to zasięg jednej dyszy – szeroka płyta może po imporcie zachodzić na pas jednej dyszy; wtedy przesuń całą grupę w bok o kilkanaście mm albo przypisz filament do odpowiedniej dyszy.": "325×300 区域是单个喷嘴的可达范围——导入后较宽的打印板可能伸入单喷嘴区域；此时将整组横向平移 10–20 mm，或将耗材分配给相应的喷嘴。",
