"Części w różnych kolorach trafiają na osobne płyty, a kolor jest w nazwie płyty. Projekt Bambu Studio ma je jako kolejne filamenty, w innych slicerach każdy kolor to osobny projekt. Bez wybranych kolorów wszystko jak dotąd.": "不同颜色的零件放在不同的打印板上，颜色写在打印板名称中。在 Bambu Studio 项目中它们是不同的耗材；在其他切片软件中每种颜色是单独的项目。不选择颜色时一切照旧。",
