"ZIP zawiera każdy rodzaj pojemnika raz i listę ilości. Pojemniki trafiają też na listę części, do szacunku i na płyty 3MF w „Przygotuj wydruk”, a w widoku 3D stoją w wysuniętej szufladzie. Wymiary wg standardu gridfinity – pasują też do innych płyt i pojemników gridfinity.": "ZIP 中每种收纳盒各一个，并附数量清单。收纳盒也会计入零件清单、估算和“准备打印”中的 3MF 打印板，3D 视图会在打开的抽屉中显示它们。尺寸遵循 gridfinity 标准——也适用于其他 gridfinity 底板和收纳盒。",
