"Widok jak we froncie. Wysokość liter: {h} mm. Dwie części: lico z wyciętym napisem i litery ({z} mm) równo z licem, licem do stołu. W 3MF etykieta to jeden obiekt z dwóch części; w projekcie Bambu Studio litery mają własny filament w kolorze napisu. Pliki STL – dwa na etykietę.": "与面板上看到的一致。字高：{h} mm。两个部件：刻出文字的面板和与之齐平的文字（{z} mm），正面朝下。在 3MF 中标签是由两个部件组成的一个对象；在 Bambu Studio 项目中文字有自己的文字颜色耗材。STL 文件——每个标签两个。",
