"Usunięto etykietę": "已删除标签",
"Pliki STL do wydrukowania – ilości, czas, filament, licznik wydrukowanych": "需打印的 STL 文件——数量、时间、耗材、已打印计数",
"Śruby, pręty, magnesy i inne elementy do kupienia": "需购买的螺丝、杆、磁铁等零件",
"Własne pojemniki gridfinity do szuflad i skrzynek (opcjonalnie)": "抽屉和储物箱的自定义 Gridfinity 收纳盒（可选）",
"Etykiety frontów z napisem i symbolem (opcjonalnie)": "带文字和符号的面板标签（可选）",
"Kopie plików STL i gotowe płyty 3MF dla Twojej drukarki": "STL 副本和适用于你打印机的 3MF 打印板",
"Następny krok:": "下一步：",
"Zwykły – kluczyk z płetwą i nakładką; ukryty – płaski, równy z frontem, z wyjmowanym kluczem.": "普通——带拨片和盖帽的钥匙；隐藏——扁平，几乎与面板齐平，钥匙可取下。",
"Listwy zębate łączą prowadnice po obu stronach, żeby szuflada nie przekrzywiała się przy wysuwaniu. Zalecane, gdy w module jest kilka szuflad.": "齿条连接两侧滑轨，抽出抽屉时不会歪斜。模块内有多个抽屉时建议使用。",
"Ile takich samych wież budujesz – lista części mnoży wszystko przez tę liczbę.": "要搭建几座相同的塔——零件清单会全部乘以这个数。",
"Głębokość wszystkich modułów wieży w kratkach gridfinity po 42 mm. Moduł jest o 20 mm dłuższy (np. 4 → 188 mm).": "塔中所有模块的深度，以 42 mm 的 Gridfinity 格为单位。模块比它长 20 mm（例如 4 → 188 mm）。",
"Wieża rośnie od spodu. Warstwa to jeden poziom: moduł z szufladami albo skrzynka z wiekiem. Wysokość 1F to 48 mm, 2F i 4F – dwa i cztery razy więcej.": "塔从底部向上搭建。每层是一个高度：抽屉模块或带盖储物箱。1F 高 48 mm，2F 和 4F 分别是 2 倍和 4 倍。",
"Podział wysokiego modułu na szuflady – np. 1F / 1F to dwie niskie szuflady w jednym module 2F.": "高模块如何分成抽屉——例如 1F / 1F 表示一个 2F 模块中有两个矮抽屉。",
"Płaskie – gładkie ściany; pod przegródki – rowki na przegródki poprzeczne i podłużne; szczelne – ścianki dzielące skrzynkę na komory.": "平底——光滑侧壁；隔板型——横向和纵向隔板的槽；密封型——将储物箱分成隔间的隔墙。",
"Grid – kratki gridfinity na wierzchu, Table – płaski blat, Bowl – misa na drobiazgi, Under Table Mount – mocowanie pod blatem, Heavyweight – wzmocniony, z rączką (tylko L i XL).": "Grid——顶部为 Gridfinity 格；Table——平顶；Bowl——小物托盘；Under Table Mount——安装在桌面下；Heavyweight——加强型，带提手（仅 L 和 XL）。",
"Podstawa pod wieżę z prętem M16 – do niej montuje się koła i stopkę.": "塔底座，带 M16 杆——轮子和支脚安装在上面。",
"Listwa z tyłu każdej warstwy, która usztywnia wieżę. Przykręca się do niej pegboard i uchwyt wysuwany. Dedykowany – na szerokość wieży, uniwersalny – dwa klocki przy bokach.": "每层背面的加固条，使塔更稳固。洞洞板和伸缩提手固定在上面。专用——与塔同宽；通用——两侧各一个块。",
"Uchwyt stały – na tyle wieży; wysuwany – rączka na prętach M16 przez kręgosłup (jak w walizce); ścienne – do zawieszenia warstw na ścianie.": "固定提手——在塔背面；伸缩提手——穿过背板的 M16 杆上的提手（像行李箱）；壁挂——把各层挂在墙上。",
"Pierwszy raz tutaj?": "第一次使用？",
"Kreator poprowadzi Cię przez 5 kroków: szablon, rozmiar, warstwy od spodu, dach i dodatki – z podglądem i szacunkiem druku. Możesz też od razu edytować „{name}” poniżej.": "向导将带你完成 5 步：模板、尺寸、从底部开始的层、顶部和附件——附带预览和打印估算。你也可以直接在下方编辑“{name}”。",
"Kreator wieży…": "塔向导…",
"Nie pokazuj": "不再显示",
