"Wysoka wieża L na kołach, z kręgosłupem, rączką i dachem z kratkami.": "带轮的高 L 塔，配背板、提手和网格顶。",
"Skrzynka narzędziowa": "工具箱",
"Szuflady na dole, na górze skrzynka z wiekiem i przegródkami, uchwyt stały.": "下层抽屉，上层带盖和隔板的储物箱，固定提手。",
"Pod blat": "桌下",
"Szuflady przykręcane pod blat biurka (dach Under Table Mount).": "拧在桌面下的抽屉（Under Table Mount 顶）。",
