"Wybierz gotowy pomysł i zmień go w kolejnych krokach – albo zacznij od pustej wieży.": "选择一个现成方案并在后续步骤中调整——或从空塔开始。",
"Szerokość wieży": "塔宽",
"wąska – pojedyncze szuflady": "窄——单个抽屉",
"średnia": "中等",
"szeroka – też 2× S obok siebie": "宽——也可两个 S 并排",
"najszersza – tylko warstwy 1F": "最宽——仅 1F 层",
