"Warstwy od spodu": "从底部开始的层",
"Każda warstwa stoi na poprzedniej. Szerokość wieży: {W} – wyżej tylko układy tej szerokości.": "每层叠在前一层上。塔宽：{W}——上方只能用同宽的布局。",
