"skrzynka {h}F": "储物箱 {h}F",
"Wkłady gridfinity, przegródki skrzynek i podział frontów każdej kolumny ustawisz później w edytorze zestawu.": "Gridfinity 底板、储物箱隔板和每列的面板划分，稍后在组合编辑器中设置。",
"Po utworzeniu zestaw możesz dalej zmieniać w edytorze: wkłady i pojemniki gridfinity w szufladach, przegródki skrzynek, pegboard. Cofnij (Ctrl+Z) wycofa utworzenie.": "创建后可在编辑器中继续修改：抽屉中的 Gridfinity 底板和收纳盒、储物箱隔板、洞洞板。撤销（Ctrl+Z）可取消创建。",
"Anuluj": "取消",
