"Kreator…": "向导…",
"Nowa wieża krok po kroku: szablon, rozmiar, warstwy, góra i dodatki": "逐步新建塔：模板、尺寸、层、顶部和附件",
"Wyzerowano licznik wydrukowanych części": "已清零已打印计数",
"Skopiowano pojemniki: {n}": "已复制收纳盒：{n}",
"Usunięto wszystkie pojemniki z układu": "已移除布局中的所有收纳盒",
"Żadna szuflada ani skrzynka w projekcie nie ma jeszcze wkładu gridfinity. Ustaw „Wkład” w szufladzie albo „wkład gridfinity” w skrzynce (edytor zestawu) – każda z nich dostanie tu własny układ pojemników. Poniżej możesz też zaprojektować układ dla szuflady spoza projektu.": "项目中还没有抽屉或储物箱带 gridfinity 内衬。请在组合编辑器中为抽屉设置“内衬”或为储物箱勾选“gridfinity 内衬”——每个都会在这里有自己的收纳盒布局。下方也可以为项目外的抽屉设计布局。",
"Pomoc": "帮助",
"Jak pracować z konfiguratorem": "如何使用配置器",
"wskaż folder z plikami STL od USSA.": "选择存放 USSA STL 文件的文件夹。",
"Wieża": "塔",
"kreatorem albo w edytorze zestawu: warstwy od spodu, dach, podstawa i dodatki.": "用向导或在组合编辑器中：从底部开始的层、顶部、底座和附件。",
"Listy części": "零件清单",
"„Do druku” (pliki STL, czas, filament, licznik wydrukowanych) i „Niedrukowane” (śruby, pręty, magnesy).": "“打印件”（STL 文件、时间、耗材、已打印计数）和“五金件”（螺丝、杆、磁铁）。",
"Opcjonalnie": "可选",
"pojemniki gridfinity do szuflad i skrzynek oraz etykiety frontów z napisem.": "抽屉和储物箱的 Gridfinity 收纳盒，以及带文字的面板标签。",
"Wydruk": "打印",
"kopie STL i płyty 3MF albo projekt slicera dla Twojej drukarki.": "STL 副本和 3MF 打印板，或适用于你打印机的切片项目。",
"Skróty klawiszowe": "快捷键",
"cofnij / ponów zmianę w projekcie (poza polami tekstowymi)": "撤销 / 重做项目更改（文本框外）",
"usuń zaznaczony pojemnik (zakładka pojemników)": "删除选中的收纳盒（收纳盒标签页）",
"zamknij okno (pomoc, ustawienia, kreator, widok 3D) albo odznacz pojemnik": "关闭窗口（帮助、设置、向导、3D 视图）或取消选择收纳盒",
"Widok 3D": "3D 视图",
"Lewy przycisk – obrót, prawy – przesuwanie, kółko – przybliżenie, dwuklik – widok domyślny, kliknięcie frontu – otwarcie szuflady albo skrzynki. Suwak „Rozsunięcie” rozkłada wieżę na części.": "左键——旋转，右键——平移，滚轮——缩放，双击——默认视图，点击面板——打开抽屉或储物箱。“分解”滑块可把塔拆分成零件。",
"Projekt zapisuje się sam w tej przeglądarce. „Projekt → Zapisz projekt” zapisuje go do pliku – na kopię albo do przeniesienia na inny komputer. Instrukcje montażu USSA (PDF) są w Ustawieniach, a przy częściach na liście – odnośniki do właściwych stron.": "项目会自动保存在此浏览器中。“项目 → 保存项目”将其写入文件——用于备份或转移到另一台电脑。USSA 组装说明（PDF）在设置中，清单中的零件会链接到相应页面。",
"„{name}”: uchwyt wysuwany montuje się na kręgosłupie – wybierz kręgosłup.": "“{name}”：伸缩提手装在背板上——请选择背板。",
"„{name}”: koła i stopka montuje się do podstawy – bez niej są pomijane.": "“{name}”：轮子和支脚安装在底座上——没有底座时会被忽略。",
"„{name}”: pegboard przykręca się do kręgosłupa – bez niego jest pomijany.": "“{name}”：洞洞板拧在背板上——没有背板时会被忽略。",
"„{name}”, warstwa {n}: skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu.": "“{name}”第 {n} 层：位于其他层下方的半宽储物箱无法原地打开。",
"Pojemniki poza siatką płyty: {n} – nie trafiają na listę części (zakładka „Pojemniki gridfinity”).": "超出底板网格的收纳盒：{n}——不会计入零件清单（“Gridfinity 收纳盒”标签页）。",
"Uwagi do projektu: {n}": "项目提示：{n}",
"Pokaż": "查看",
"Nowy projekt": "新建项目",
"Nowy projekt – poprzedni przywróci „Cofnij”": "新建项目——“撤销”可恢复之前的项目",
"Dodano pojemniki: {n}": "已添加收纳盒：{n}",
"Wypełnij wolne kratki:": "填充空格：",
"Wnętrze": "内部",
"wkład gridfinity we wszystkich szufladach": "所有抽屉使用 gridfinity 内衬",
"wkład gridfinity we wszystkich skrzynkach": "所有储物箱使用 gridfinity 内衬",
"Etykiety z projektu": "从项目生成标签",
"Po jednej etykiecie na każdy front szuflady i skrzynki w projekcie, z opisem miejsca. Kolejne kliknięcie dopisuje tylko nowe fronty.": "为项目中每个抽屉和储物箱面板各生成一个标签，并注明位置。再次点击只会添加新的面板。",
"Dodano etykiety z projektu: {n}": "已从项目添加标签：{n}",
"Wszystkie fronty projektu mają już etykiety": "项目中的所有面板都已有标签",
"Puste etykiety USSA są nadal na liście części – fronty, którym nie wpiszesz napisu, dostaną pustą etykietę.": "USSA 空白标签仍在零件清单中——未填写文字的面板将使用空白标签。",
"Nie drukuj pustych": "不打印空白标签",
"Wyłączono puste etykiety na liście części": "已从零件清单中移除空白标签",
"Miejsce: {g}": "位置：{g}",
"Puste etykiety są wyłączone, a liczba etykiet z napisem nie zgadza się z liczbą frontów: {list}.": "空白标签已关闭，但带文字的标签数量与面板数量不一致：{list}。",
"Label (szuflady, skrzynki 2F i 4F) {a} z {b}": "Label（抽屉、2F 和 4F 储物箱）{a} / {b}",
"Label for Sustainers (skrzynki 1F) {a} z {b}": "Label for Sustainers（1F 储物箱）{a} / {b}",
"Konfigurator VAULT: odmowa dostępu. Adres {host} nie jest dozwolony – dopisz go do zmiennej VAULT_HOSTS (np. VAULT_HOSTS={host}) i uruchom serwer ponownie.": "VAULT 配置器：拒绝访问。地址 {host} 不在允许列表中——请将其添加到 VAULT_HOSTS 变量（例如 VAULT_HOSTS={host}）并重新启动服务器。",
"Za duże zapytanie.": "请求过大。",
"Za dużo sztuk w zleceniu (najwyżej {n}).": "任务中的零件过多（最多 {n} 个）。",
