"Hidden Key Part 2 to wyjmowana rączka do obracania ukrytych zamków – pasuje do wszystkich szuflad, więc wystarczy jedna na projekt.": "Hidden Key Part 2 是用于转动隐藏锁的可拆卸把手——适用于所有抽屉，因此每个项目一把就够了。",
