"kroki dla jednej wieży, powtórz {n}×": "单座塔的步骤，重复 {n} 次",
"Kroki od spodu wieży: części i elementy niedrukowane na jedną wieżę, przy częściach strony instrukcji USSA (gdy PDF-y są w bibliotece). Zaznaczone kroki zapisują się z projektem.": "从塔底向上的步骤：单座塔所需的零件和五金件，零件旁附 USSA 说明书页码（库中有 PDF 时）。勾选的步骤随项目保存。",
