"_napis": "_text",
"Uchwyt ścienny przykręca się do tyłu modułów w miejscu kręgosłupa – wybierz kręgosłup „brak”.": "壁挂支架拧在模块背面、脊柱所在的位置 – 请把脊柱设为「无」。",
"„{name}”: uchwyt ścienny przykręca się do tyłu modułów w miejscu kręgosłupa – z kręgosłupem jest pomijany.": "「{name}」：壁挂支架拧在模块背面、脊柱所在的位置 – 有脊柱时将被忽略。",
"Uchwyt stały przykręca się do kręgosłupa – wybierz kręgosłup.": "固定把手拧在脊柱上 – 请选择脊柱。",
"„{name}”: uchwyt stały przykręca się do kręgosłupa – bez niego jest pomijany.": "「{name}」：固定把手拧在脊柱上 – 没有脊柱时将被忽略。",
"kółka meblowe (Casters Mode)": "万向轮（Casters Mode）",
"Kółka meblowe stoją tam, gdzie koła i stopka – zaznacz podstawę i odznacz koła i stopkę.": "万向轮安装在轮子和支脚的位置 – 请勾选底座，并取消勾选轮子和支脚。",
"Kółko meblowe skrętne z trzpieniem gwintowanym M8": "M8 螺杆万向轮",
"kółka meblowe (Casters Mode) – trzpień w otworze Ø 7 mm w spodzie podstawy": "万向轮（Casters Mode）– 螺杆插入底座底面的 Ø 7 mm 孔",
"„{name}”: kółka meblowe stoją tam, gdzie koła i stopka – przy kołach albo stopce są pomijane.": "「{name}」：万向轮安装在轮子和支脚的位置 – 选了轮子或支脚时将被忽略。",
"Pojemniki wyższe niż miejsce w szufladzie albo skrzynce: {n} (zakładka „Pojemniki gridfinity”).": "高于抽屉或储物箱内空间的收纳盒：{n}（「Gridfinity 收纳盒」选项卡）。",
"Etykiety z literami niższymi niż 3 mm: {n} – skróć napis albo podziel go na 2 linie.": "字母高度小于 3 mm 的标签：{n} – 请缩短文字或分成 2 行。",
