"ilość na płytach różni się od listy – przygotuj wydruk ponownie": "打印板上的数量与清单不同——请重新准备打印",
"przegródki Grid Dividers": "Grid Dividers 隔板",
"Płyta gridfinity na dnie pudełka – na niej stoją pojemniki gridfinity (zakładka „Pojemniki gridfinity”); albo przegródki Grid Dividers wsuwane w otwory dna (zakładka „Przegródki”).": "抽屉盒底部的 Gridfinity 底板——上面放 Gridfinity 收纳盒（“Gridfinity 收纳盒”页）；或插入底部孔中的 Grid Dividers 隔板（“隔板”页）。",
"za krótka – najkrótsza przegródka ma {n} odstępów": "太短——最短的隔板为 {n} 个间距",
"za długa – najdłuższa przegródka ma {n} odstępów": "太长——最长的隔板为 {n} 个间距",
"krzyżuje się z inną przegródką": "与另一隔板交叉",
"nachodzi na inną przegródkę": "与另一隔板重叠",
"za blisko równoległej przegródki – stopy nachodzą (odstęp najmniej 3 otwory)": "离平行隔板太近——底脚重叠（至少间隔 3 个孔）",
"za blisko ścianki – stopa przegródki na nią wchodzi": "离侧壁太近——隔板底脚会顶到侧壁",
"Zaprojektuj przegródki Grid Dividers dla tej szuflady ({n} szt.)": "为此抽屉设计 Grid Dividers 隔板（{n} 件）",
"Przegródki Grid Dividers z błędem: {n} – nie trafiają na listę części ({where}).": "有错误的 Grid Dividers 隔板：{n}——未计入零件清单（{where}）。",
"Przegródki szuflad (Grid Dividers)": "抽屉隔板（Grid Dividers）",
"Żadna szuflada nie ma wkładu „przegródki Grid Dividers”. Ustaw go w edytorze zestawu: Wkład → przegródki Grid Dividers.": "没有抽屉使用“Grid Dividers 隔板”内衬。请在组合编辑器中设置：内衬 → Grid Dividers 隔板。",
"Przegródki wsuwa się w otwory w dnie pudełka szuflady (co 10,5 mm) – zamiast płyty gridfinity.": "隔板插入抽屉盒底部的孔中（间距 10.5 mm）——代替 Gridfinity 底板。",
"Szuflada:": "抽屉：",
"{n} przegr.": "{n} 块隔板",
"Wysokość:": "高度：",
"20 mm – niskie przegródki do każdej szuflady; 34,5 mm – pełna wysokość szuflady 1F; 82,5 mm – pełna wysokość szuflady 2F.": "20 mm——适用于任何抽屉的矮隔板；34.5 mm——1F 抽屉全高；82.5 mm——2F 抽屉全高。",
"Piny:": "销钉：",
