"Serwer działa na starszej wersji programu (inne obszary drukarek). Zamknij okno konsoli serwera, uruchom ponownie konfigurator (uruchom.bat lub run.sh) i odśwież tę stronę.": "El servidor ejecuta una versión anterior del programa (otras áreas de impresora). Cierra la ventana de consola del servidor, vuelve a iniciar el configurador (run.bat o run.sh) y recarga esta página.",
"Sprawdzam serwer…": "Comprobando el servidor…",
"Konfigurator nie jest uruchomiony przez serwer, więc przeglądarka nie ma dostępu do plików.": "El configurador no se ejecuta a través del servidor, así que el navegador no tiene acceso a los archivos.",
"Zamknij tę kartę i uruchom uruchom.bat (Windows) albo run.sh (macOS, Linux) w folderze konfigurator (otworzy konfigurator z obsługą plików). Projekt zapisuje się w przeglądarce osobno dla każdego adresu – przenieś go przyciskami Zapisz/Wczytaj projekt.": "Cierra esta pestaña y ejecuta run.bat (Windows) o run.sh (macOS, Linux) en la carpeta konfigurator (abre el configurador con acceso a los archivos). El proyecto se guarda en el navegador por separado para cada dirección – trasládalo con los botones Guardar/Cargar proyecto.",
"Możesz też pobrać zlecenie i uruchomić je ręcznie:": "También puedes descargar el trabajo y ejecutarlo manualmente:",
