"Otwórz plik 3MF w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory dla części „Turn On Supports”. Części są w orientacji z plików STL.": "Abre el archivo 3MF en Bambu Studio / OrcaSlicer / PrusaSlicer, elige el perfil y el filamento, y activa los soportes para las piezas «Turn On Supports». Las piezas mantienen la orientación de los archivos STL.",
