"Obszar 325×300 to zasięg jednej dyszy – szeroka płyta może po imporcie zachodzić na pas jednej dyszy; wtedy przesuń całą grupę w bok o kilkanaście mm albo przypisz filament do odpowiedniej dyszy.": "El área de 325×300 es el alcance de una sola boquilla – tras importar, una placa ancha puede invadir la franja de una sola boquilla; en ese caso desplaza todo el grupo de lado 10–20 mm o asigna el filamento a la boquilla correspondiente.",
