"Pliki 3MF zawierają rozmieszczone części (w orientacji z plików STL). Otwórz w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory tam, gdzie lista każe („Turn On Supports”).": "Los archivos 3MF contienen las piezas colocadas (en la orientación de los archivos STL). Ábrelos en Bambu Studio / OrcaSlicer / PrusaSlicer, elige el perfil y el filamento, y activa los soportes donde lo indique la lista («Turn On Supports»).",
