"Podstawa głębokości 6 i 7 ma ok. 280–325 mm długości; USSA daje ją w całości (Whole) albo w 2 częściach (Part 1 + Part 2) dla mniejszych drukarek. Dostępne po zaznaczeniu podstawy przy głębokości 6 lub 7.": "La base para profundidades 6 y 7 mide unos 280–325 mm; USSA la ofrece entera (Whole) o en 2 partes (Part 1 + Part 2) para impresoras más pequeñas. Disponible cuando se elige la base con profundidad 6 o 7.",
"Wersja programu: {v}": "Versión del programa: {v}",
"Pliki STL systemu VAULT": "Archivos STL de VAULT",
"Konfigurator potrzebuje folderu z plikami VAULT od USSA Design (podfoldery 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Wskaż go – program zapamięta ścieżkę i odczyta listę plików.": "El configurador necesita la carpeta con los archivos VAULT de USSA Design (subcarpetas 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Indícala – el programa recuerda la ruta y lee la lista de archivos.",
"Znaleziono bibliotekę – kliknij „Sprawdź i skanuj” (za pierwszym razem ok. 2–3 minut).": "Biblioteca encontrada – haz clic en «Comprobar y escanear» (unos 2–3 minutos la primera vez).",
