"Wskaż folder z plikami STL w oknie konfiguratora. Pliki VAULT sprzedaje USSA Design: {url}": "Indica la carpeta STL en la ventana del configurador. Los archivos VAULT los vende USSA Design: {url}",
"Okno wyboru folderu jest niedostępne (Python bez tkinter) – wpisz ścieżkę ręcznie.": "El selector de carpetas no está disponible (Python sin tkinter) – escribe la ruta.",
"Okno wyboru folderu jest już otwarte.": "El selector de carpetas ya está abierto.",
"Wskaż folder z plikami VAULT (STL)": "Elige la carpeta con los archivos VAULT (STL)",
"VAULT to system pojemników firmy USSA Design. Ten program jest nieoficjalnym narzędziem i nie zawiera plików STL – kupisz je u producenta:": "VAULT es un sistema de almacenamiento de USSA Design. Este programa es una herramienta no oficial y no incluye los archivos STL – cómpralos al fabricante:",
