"Podaj pełną ścieżkę folderu, np. D:\\VAULT\\do_druku.": "Escribe la ruta completa de la carpeta, p. ej. D:\\VAULT\\do_druku.",
"Folder na wydruki nie może leżeć w bibliotece plików VAULT ({dir}) – skanowanie wzięłoby kopie STL za części.": "La carpeta de salida no puede estar dentro de la biblioteca de archivos VAULT ({dir}) – el escaneo trataría las copias STL como piezas.",
"Folder na wydruki nie może leżeć w folderze programu.": "La carpeta de salida no puede estar dentro de la carpeta del programa.",
"Nie można utworzyć folderu {dir}: {err}": "No se puede crear la carpeta {dir}: {err}",
"Uwaga: serwer nasłuchuje na {bind} (VAULT_BIND) i nie ma logowania – udostępniaj go tylko w zaufanej sieci. Dozwolone adresy API: {hosts}": "Atención: el servidor escucha en {bind} (VAULT_BIND) y no tiene inicio de sesión – compártelo solo en una red de confianza. Direcciones permitidas para la API: {hosts}",
"Płyty są w projekcie {slicer} (części z TPU w osobnym): {file} (profile systemowe: {printer}, {process}, {filament}).": "Las placas están en el proyecto de {slicer} (las piezas de TPU, en otro aparte): {file} (perfiles del sistema: {printer}, {process}, {filament}).",
". Wszystkie płyty trafią do jednego projektu {slicer} z profilami systemowymi: {printer}, {process}, {filament} (części z TPU – osobny projekt).": ". Todas las placas van a un único proyecto de {slicer} con perfiles del sistema: {printer}, {process}, {filament} (piezas de TPU – en un proyecto aparte).",
"jeden projekt {slicer} ze wszystkimi płytami (zamiast osobnych plików 3MF)": "un proyecto de {slicer} con todas las placas (en lugar de archivos 3MF separados)",
"Projekt {slicer}: {file}": "Proyecto de {slicer}: {file}",
"Otwórz projekt w {slicer} (Plik → Otwórz projekt) – płyty, drukarka, proces i filament są już ustawione. Włącz podpory dla części „Turn On Supports”. Części są w orientacji z plików STL.": "Abre el proyecto en {slicer} (Archivo → Abrir proyecto) – las placas, la impresora, el proceso y el filamento ya están configurados. Activa los soportes para las piezas «Turn On Supports». Las piezas están en la orientación de los archivos STL.",
