"Projekt jest dla {slicer}. W innym slicerze (np. OrcaSlicer) wybierz po otwarciu swoją drukarkę z listy albo użyj osobnych plików 3MF.": "El proyecto es para {slicer}. En otro slicer (p. ej. OrcaSlicer), tras abrirlo elige tu impresora en la lista, o usa los archivos 3MF separados.",
"Części w różnych kolorach trafiają na osobne płyty, a kolor jest w nazwie płyty. Projekt Bambu Studio ma je jako kolejne filamenty, w innych slicerach każdy kolor to osobny projekt. Bez wybranych kolorów wszystko jak dotąd.": "Las piezas de distintos colores van a placas separadas, con el color en el nombre de la placa. Un proyecto de Bambu Studio las tiene como filamentos separados; en otros slicers cada color es un proyecto aparte. Sin colores elegidos todo funciona como antes.",
