"Wyczyść folder wyników": "Limpiar carpeta de salida",
"Nowe narzędzie: naprawa siatek STL": "Nueva herramienta: reparación de mallas STL",
"Bambu Studio proponuje naprawę plików VAULT przy każdym wczytaniu. napraw_stl.bat w folderze programu naprawia całą bibliotekę za jednym razem tą samą usługą Windows i zapisuje jej naprawioną kopię, którą wskazujesz potem jako bibliotekę.": "Bambu Studio ofrece reparar los archivos VAULT cada vez que se cargan. repair_stl.bat en la carpeta del programa repara toda la biblioteca de una vez con el mismo servicio de Windows y escribe una copia reparada, que luego eliges como biblioteca.",
