"Zamknij": "Cerrar",
"po 1 w każdej szczelinie ściany modułu: 2 na każde F (L² i XL² – 3)": "1 en cada ranura de las paredes del módulo: 2 por F (L² y XL² – 3)",
"Skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu: warstwa wyżej jest spięta zatrzaskami z wiekiem i z modułem obok, więc trzeba najpierw zdjąć całą górę wieży. Skrzynka na całą szerokość otwiera się razem z górą (wieko odchyla się z warstwami nad nim).": "Una caja de media anchura bajo otra capa no se abre en su sitio: la capa de encima está enganchada a su tapa y al módulo de al lado, así que primero tienes que quitar toda la parte superior de la torre. Una caja de anchura completa se abre junto con la parte superior (la tapa se inclina hacia atrás con las capas que lleva encima).",
