"generuje konfigurator (zakładka „Pojemniki gridfinity”)": "generado por el configurador (pestaña «Contenedores gridfinity»)",
"ZIP zawiera każdy rodzaj pojemnika raz i listę ilości. Pojemniki trafiają też na listę części, do szacunku i na płyty 3MF w „Przygotuj wydruk”, a w widoku 3D stoją w wysuniętej szufladzie. Wymiary wg standardu gridfinity – pasują też do innych płyt i pojemników gridfinity.": "El ZIP tiene cada tipo de contenedor una vez y una lista de cantidades. Los contenedores también pasan a la lista de piezas, la estimación y las placas 3MF de «Preparar impresión», y la vista 3D los muestra en el cajón abierto. Las dimensiones siguen el estándar gridfinity – también encajan en otras baseplates y contenedores gridfinity.",
