"Czerwona ramka: najwyżej {mm} mm nad dnem – pojemnik do {a} jedn. z rantem, {b} bez rantu.": "Marco rojo: como máximo {mm} mm sobre el fondo – contenedores de hasta {a} unidades con borde, {b} sin él.",
"Pegboard przykręca się do kręgosłupa – wybierz kręgosłup.": "El pegboard se atornilla al backbone – elige un backbone.",
"Moduły, fronty, zamki, pudełka, dachy, podstawa, stopki, koła, kręgosłup, pegboard i uchwyty z plików STL (uproszczone; pierwsze otwarcie trwa dłużej); złożone – moduły zapięte jak w rzeczywistości, rączka wsunięta.": "Módulos, facades, cierres, cuerpos de cajón, techos, base, patas, ruedas, backbone, pegboard y asas a partir de los archivos STL (simplificados; la primera apertura tarda más); ensamblado – módulos enganchados como en la realidad, asa recogida.",
"jedna na otwór w uchwycie (1F – bez otworu)": "uno por agujero del soporte (1F – sin agujero)",
