"Serwer działa ze starszym generatorem pojemników (płyty i lekkie dno wyszłyby źle) – zamknij jego okno i uruchom konfigurator ponownie.": "El servidor ejecuta un generador de contenedores anterior (las baseplates y el fondo ligero saldrían mal) – cierra su ventana y vuelve a iniciar el configurador.",
