"Widok jak we froncie. Wysokość liter: {h} mm. Napis {z} mm nad etykietą – w projekcie Bambu Studio filament zmienia się sam na warstwie od {t} mm (kolor napisu, gdy inny niż kolor etykiety); w innym slicerze zmień go ręcznie.": "Vista como en el frente. Altura de las letras: {h} mm. Texto {z} mm sobre la etiqueta – en un proyecto de Bambu Studio el filamento cambia solo en la capa de {t} mm (color del texto, si es distinto del de la etiqueta); en otro laminador cámbialo a mano.",
"etykiety": "etiquetas",
