"na listę części – zamiast tylu samo pustych etykiet": "en la lista de piezas – en lugar de otras tantas etiquetas en blanco",
"Etykieta to plik USSA z Twojej biblioteki (Label albo Label for Sustainers) z wypukłym napisem i symbolem. 3MF: wszystkie etykiety ułożone na płytach drukarki z „Przygotuj wydruk”. Drukuj licem do góry; drugi kolor – zmiana filamentu na wysokości wierzchu etykiety.": "La etiqueta es el archivo USSA de tu biblioteca (Label o Label for Sustainers) con texto y símbolo en relieve. 3MF: todas las etiquetas colocadas en las placas de la impresora de «Preparar impresión». Imprime con la cara visible hacia arriba; segundo color – cambio de filamento a la altura de la cara superior de la etiqueta.",
