"wklęsły – druk licem do stołu": "grabado – imprimir con la cara visible sobre la cama",
"głębokość napisu": "profundidad del texto",
"Widok jak we froncie. Wysokość liter: {h} mm. Napis wycięty na {z} mm w licu; plik leży licem do stołu – gładkie lico i ostre krawędzie liter (jeden kolor).": "Vista como en el frontal. Altura de las letras: {h} mm. Texto grabado {z} mm en la cara; el archivo está con la cara visible sobre la cama – cara lisa y bordes nítidos (un color).",
"puste etykiety (Label) na liście części": "etiquetas en blanco (Label) en la lista de piezas",
"Wyłącz, jeśli etykiet nie drukujesz albo robisz je w zakładce „Etykiety” (te zostają na liście).": "Desactívalo si no imprimes etiquetas o las haces en la pestaña «Etiquetas» (esas se quedan en la lista).",
"wpuszczony – drugi filament, druk licem do stołu": "incrustado – segundo filamento, imprimir con la cara visible sobre la cama",
"grubość napisu": "grosor del texto",
"kolor napisu (wspólny dla etykiet)": "color del texto (común para las etiquetas)",
"Widok jak we froncie. Wysokość liter: {h} mm. Dwie części: lico z wyciętym napisem i litery ({z} mm) równo z licem, licem do stołu. W 3MF etykieta to jeden obiekt z dwóch części; w projekcie Bambu Studio litery mają własny filament w kolorze napisu. Pliki STL – dwa na etykietę.": "Vista como en el frontal. Altura de las letras: {h} mm. Dos piezas: la cara con el texto recortado y las letras ({z} mm) a ras, con la cara visible sobre la cama. En el 3MF la etiqueta es un objeto de dos piezas; en un proyecto de Bambu Studio las letras tienen su propio filamento en el color del texto. Archivos STL – dos por etiqueta.",
"Wybierz…": "Elegir…",
