"wpuszczony – drugi filament, równo z półką": "incrustado – segundo filamento, a ras del soporte",
"wklęsły – jeden kolor": "grabado – un color",
"kolor napisu (wspólny z etykietami)": "color del texto (común con las etiquetas)",
"Przegródki od lewej, najpierw przedni rząd.": "Compartimentos de izquierda a derecha, primero la fila delantera.",
"Symbol…": "Símbolo…",
"Bez perspektywy": "Sin perspectiva",
"Rozsunięcie wieży we wszystkich osiach – warstwy w pionie, fronty do przodu, moduły i koła na boki, kręgosłup do tyłu": "Despiece de la torre en todos los ejes – capas hacia arriba, frentes hacia delante, módulos y ruedas a los lados, columna hacia atrás",
"Rozsunięcie": "Despiece",
"Wczytuję symbole…": "Cargando símbolos…",
"Nie udało się wczytać symboli: {e}": "No se pudieron cargar los símbolos: {e}",
