"Przygotowanie wydruku": "Préparation de l'impression",
"Serwer działa na starszej wersji programu (inne obszary drukarek). Zamknij okno konsoli serwera, uruchom ponownie konfigurator (uruchom.bat lub run.sh) i odśwież tę stronę.": "Le serveur exécute une ancienne version du programme (zones d'imprimante différentes). Fermez la fenêtre de console du serveur, relancez le configurateur (run.bat ou run.sh) et rechargez cette page.",
"Sprawdzam serwer…": "Vérification du serveur…",
"Konfigurator nie jest uruchomiony przez serwer, więc przeglądarka nie ma dostępu do plików.": "Le configurateur ne passe pas par le serveur, le navigateur n'a donc pas accès aux fichiers.",
"Zamknij tę kartę i uruchom uruchom.bat (Windows) albo run.sh (macOS, Linux) w folderze konfigurator (otworzy konfigurator z obsługą plików). Projekt zapisuje się w przeglądarce osobno dla każdego adresu – przenieś go przyciskami Zapisz/Wczytaj projekt.": "Fermez cet onglet et lancez run.bat (Windows) ou run.sh (macOS, Linux) dans le dossier konfigurator (il ouvre le configurateur avec accès aux fichiers). Le projet est stocké dans le navigateur séparément pour chaque adresse – transférez-le avec les boutons Enregistrer/Charger le projet.",
"Możesz też pobrać zlecenie i uruchomić je ręcznie:": "Vous pouvez aussi télécharger la tâche et l'exécuter manuellement :",
