"Otwórz plik 3MF w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory dla części „Turn On Supports”. Części są w orientacji z plików STL.": "Ouvrez le fichier 3MF dans Bambu Studio / OrcaSlicer / PrusaSlicer, choisissez le profil et le filament, et activez les supports pour les pièces « Turn On Supports ». Les pièces conservent l'orientation des fichiers STL.",
