"vault-projekt.json": "vault-projet.json",
"To nie jest plik projektu konfiguratora.": "Ce n'est pas un fichier de projet du configurateur.",
"Brak listy plików – ustaw katalog biblioteki w Ustawieniach → „Biblioteka plików” (uruchom.bat lub run.sh) albo uruchom: python skanuj.py \"D:\\ścieżka\\vault\"": "Pas de liste de fichiers – définissez le dossier de la bibliothèque dans Paramètres → « Bibliothèque de fichiers » (run.bat ou run.sh) ou lancez : python skanuj.py \"D:\\chemin\\vault\"",
