"Obszar 325×300 to zasięg jednej dyszy – szeroka płyta może po imporcie zachodzić na pas jednej dyszy; wtedy przesuń całą grupę w bok o kilkanaście mm albo przypisz filament do odpowiedniej dyszy.": "La zone 325×300 correspond à la portée d'une seule buse – après l'importation, une plaque large peut empiéter sur une bande accessible à une seule buse ; décalez alors tout le groupe latéralement de 10–20 mm ou attribuez le filament à la buse correspondante.",
