"Pliki 3MF zawierają rozmieszczone części (w orientacji z plików STL). Otwórz w Bambu Studio / OrcaSlicer / PrusaSlicer, wybierz profil i filament, włącz podpory tam, gdzie lista każe („Turn On Supports”).": "Les fichiers 3MF contiennent les pièces disposées (dans l'orientation des fichiers STL). Ouvrez-les dans Bambu Studio / OrcaSlicer / PrusaSlicer, choisissez le profil et le filament, et activez les supports là où la liste l'indique (« Turn On Supports »).",
