"Podstawa głębokości 6 i 7 ma ok. 280–325 mm długości; USSA daje ją w całości (Whole) albo w 2 częściach (Part 1 + Part 2) dla mniejszych drukarek. Dostępne po zaznaczeniu podstawy przy głębokości 6 lub 7.": "Le socle pour les profondeurs 6 et 7 mesure environ 280–325 mm de long ; USSA le fournit entier (Whole) ou en 2 parties (Part 1 + Part 2) pour les petites imprimantes. Disponible lorsque le socle est sélectionné en profondeur 6 ou 7.",
"Wersja programu: {v}": "Version du programme : {v}",
"Pliki STL systemu VAULT": "Fichiers STL VAULT",
"Konfigurator potrzebuje folderu z plikami VAULT od USSA Design (podfoldery 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Wskaż go – program zapamięta ścieżkę i odczyta listę plików.": "Le configurateur a besoin du dossier contenant les fichiers VAULT de USSA Design (sous-dossiers 01. DRAWERS, 02. SUSTAINERS, 03. MODIFICATIONS). Indiquez-le – le programme mémorise le chemin et lit la liste des fichiers.",
"Znaleziono bibliotekę – kliknij „Sprawdź i skanuj” (za pierwszym razem ok. 2–3 minut).": "Bibliothèque trouvée – cliquez sur « Vérifier et analyser » (environ 2–3 minutes la première fois).",
