"VAULT to system pojemników firmy USSA Design. Ten program jest nieoficjalnym narzędziem i nie zawiera plików STL – kupisz je u producenta:": "VAULT est un système de rangement de USSA Design. Ce programme est un outil non officiel et ne contient pas les fichiers STL – achetez-les auprès du fabricant :",
