"Podaj pełną ścieżkę folderu, np. D:\\VAULT\\do_druku.": "Saisissez le chemin complet du dossier, par ex. D:\\VAULT\\do_druku.",
"Folder na wydruki nie może leżeć w bibliotece plików VAULT ({dir}) – skanowanie wzięłoby kopie STL za części.": "Le dossier de sortie ne peut pas se trouver dans la bibliothèque de fichiers VAULT ({dir}) – l'analyse traiterait les copies STL comme des pièces.",
"Folder na wydruki nie może leżeć w folderze programu.": "Le dossier de sortie ne peut pas se trouver dans le dossier du programme.",
"Nie można utworzyć folderu {dir}: {err}": "Impossible de créer le dossier {dir} : {err}",
"Uwaga: serwer nasłuchuje na {bind} (VAULT_BIND) i nie ma logowania – udostępniaj go tylko w zaufanej sieci. Dozwolone adresy API: {hosts}": "Attention : le serveur écoute sur {bind} (VAULT_BIND) et n'a pas d'authentification – partagez-le uniquement sur un réseau de confiance. Adresses API autorisées : {hosts}",
"Płyty są w projekcie {slicer} (części z TPU w osobnym): {file} (profile systemowe: {printer}, {process}, {filament}).": "Les plaques sont dans le projet {slicer} (pièces TPU dans un projet séparé) : {file} (profils système : {printer}, {process}, {filament}).",
". Wszystkie płyty trafią do jednego projektu {slicer} z profilami systemowymi: {printer}, {process}, {filament} (części z TPU – osobny projekt).": ". Toutes les plaques vont dans un seul projet {slicer} avec les profils système : {printer}, {process}, {filament} (pièces TPU – projet séparé).",
"jeden projekt {slicer} ze wszystkimi płytami (zamiast osobnych plików 3MF)": "un seul projet {slicer} avec toutes les plaques (au lieu de fichiers 3MF séparés)",
"Projekt {slicer}: {file}": "Projet {slicer} : {file}",
"Otwórz projekt w {slicer} (Plik → Otwórz projekt) – płyty, drukarka, proces i filament są już ustawione. Włącz podpory dla części „Turn On Supports”. Części są w orientacji z plików STL.": "Ouvrez le projet dans {slicer} (Fichier → Ouvrir un projet) – les plaques, l'imprimante, le processus et le filament sont déjà définis. Activez les supports pour les pièces « Turn On Supports ». Les pièces sont dans l'orientation des fichiers STL.",
