"Projekt jest dla {slicer}. W innym slicerze (np. OrcaSlicer) wybierz po otwarciu swoją drukarkę z listy albo użyj osobnych plików 3MF.": "Le projet est destiné à {slicer}. Dans un autre slicer (par ex. OrcaSlicer), choisissez votre imprimante dans la liste après l'ouverture, ou utilisez les fichiers 3MF séparés.",
"Części w różnych kolorach trafiają na osobne płyty, a kolor jest w nazwie płyty. Projekt Bambu Studio ma je jako kolejne filamenty, w innych slicerach każdy kolor to osobny projekt. Bez wybranych kolorów wszystko jak dotąd.": "Les pièces de couleurs différentes vont sur des plaques séparées, avec la couleur dans le nom de la plaque. Un projet Bambu Studio les contient comme filaments séparés ; dans les autres slicers, chaque couleur est un projet séparé. Sans couleurs choisies, tout fonctionne comme avant.",
