"Usuwa wcześniejsze wyniki konfiguratora (foldery ze znacznikiem .vault-wynik); inne pliki zostają.": "Supprime les résultats précédents du configurateur (dossiers avec le marqueur .vault-wynik) ; les autres fichiers restent.",
