"najpierw wyczyść folder wyników (usuwa wcześniejsze wyniki)": "vider d'abord le dossier de sortie (supprime les résultats précédents)",
"Usunięto wcześniejsze wyniki: {n}": "Résultats précédents supprimés : {n}",
"czyszczenie folderu wyników…": "vidage du dossier de sortie…",
"Wyczyść folder wyników": "Vider le dossier de sortie",
"Nowe narzędzie: naprawa siatek STL": "Nouvel outil : réparation des maillages STL",
"Bambu Studio proponuje naprawę plików VAULT przy każdym wczytaniu. napraw_stl.bat w folderze programu naprawia całą bibliotekę za jednym razem tą samą usługą Windows i zapisuje jej naprawioną kopię, którą wskazujesz potem jako bibliotekę.": "Bambu Studio propose de réparer les fichiers VAULT à chaque chargement. repair_stl.bat, dans le dossier du programme, répare toute la bibliothèque en une fois avec le même service Windows et écrit une copie réparée, que vous sélectionnez ensuite comme bibliothèque.",
"Opis i narzędzie na GitHubie": "Description et outil sur GitHub",
"nie pokazuj więcej": "ne plus afficher",
"Zamknij": "Fermer",
"po 1 w każdej szczelinie ściany modułu: 2 na każde F (L² i XL² – 3)": "1 dans chaque fente des parois du module : 2 par F (L² et XL² – 3)",
"Skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu: warstwa wyżej jest spięta zatrzaskami z wiekiem i z modułem obok, więc trzeba najpierw zdjąć całą górę wieży. Skrzynka na całą szerokość otwiera się razem z górą (wieko odchyla się z warstwami nad nim).": "Un caisson demi-largeur sous un autre étage ne s'ouvre pas sur place : l'étage au-dessus est verrouillé à son couvercle et au module voisin, il faut donc d'abord retirer toute la partie supérieure de la tour. Un caisson pleine largeur s'ouvre avec la partie supérieure (le couvercle bascule vers l'arrière avec les étages qu'il porte).",
"Instaluję pakiety winrt ({pakiety})…": "Installation des paquets winrt ({pakiety})…",
"Nie udało się zainstalować pakietów winrt – zainstaluj ręcznie: {polecenie}": "Impossible d'installer les paquets winrt – installez-les manuellement : {polecenie}",
