"generuje konfigurator (zakładka „Pojemniki gridfinity”)": "généré par le configurateur (onglet « Bacs gridfinity »)",
"ZIP zawiera każdy rodzaj pojemnika raz i listę ilości. Pojemniki trafiają też na listę części, do szacunku i na płyty 3MF w „Przygotuj wydruk”, a w widoku 3D stoją w wysuniętej szufladzie. Wymiary wg standardu gridfinity – pasują też do innych płyt i pojemników gridfinity.": "Le ZIP contient chaque type de bac une seule fois et une liste des quantités. Les bacs sont aussi ajoutés à la liste des pièces, à l'estimation et aux plaques 3MF dans « Préparer l'impression », et la vue 3D les montre dans le tiroir ouvert. Les dimensions suivent le standard gridfinity – ils conviennent aussi à d'autres baseplates et bacs gridfinity.",
