"Usuń układ": "Supprimer la disposition",
"Czerwona ramka: najwyżej {mm} mm nad dnem – pojemnik do {a} jedn. z rantem, {b} bez rantu.": "Cadre rouge : au plus {mm} mm au-dessus du fond – bacs jusqu'à {a} unités avec rebord, {b} sans.",
"Pegboard przykręca się do kręgosłupa – wybierz kręgosłup.": "Le pegboard se visse sur le backbone – choisissez un backbone.",
"Moduły, fronty, zamki, pudełka, dachy, podstawa, stopki, koła, kręgosłup, pegboard i uchwyty z plików STL (uproszczone; pierwsze otwarcie trwa dłużej); złożone – moduły zapięte jak w rzeczywistości, rączka wsunięta.": "Modules, façades, serrures, boîtes, toits, socle, pieds, roues, backbone, pegboard et poignées issus des fichiers STL (simplifiés ; la première ouverture prend plus de temps) ; assemblé – modules verrouillés comme en réalité, poignée rentrée.",
"jedna na otwór w uchwycie (1F – bez otworu)": "une par trou de la fixation (1F – pas de trou)",
"płyta pod pojemniki (też na liście części)": "baseplate sous les bacs (aussi dans la liste des pièces)",
