"Płyta {sx} × {sy} mm (jak płyta USSA), {c} × {r} kratek; {n} części – stół {w} × {d} mm z „Przygotuj wydruk”.": "Baseplate {sx} × {sy} mm (comme celle d'USSA), {c} × {r} cases ; {n} pièces – plateau {w} × {d} mm de « Préparer l'impression ».",
"Pobierz płytę (ZIP)": "Télécharger la baseplate (ZIP)",
