"wysokość, półka, zaokrąglenie, rant, magnesy i dno jak we wzorze; przegródki bez zmian": "hauteur, support d'étiquette, arrondi, rebord, aimants et fond tels que définis ici ; séparateurs inchangés",
"Serwer działa ze starszym generatorem pojemników (płyty i lekkie dno wyszłyby źle) – zamknij jego okno i uruchom konfigurator ponownie.": "Le serveur utilise un ancien générateur de bacs (les baseplates et le fond allégé seraient incorrects) – fermez sa fenêtre et relancez le configurateur.",
"{n} pojemników wychodzi poza siatkę albo stoi na zabudowanym polu płyty – przesuń je albo usuń; nie trafią do pliku ZIP ani na listę części.": "{n} bacs sont hors de la grille ou sur la case fermée de la baseplate – déplacez-les ou supprimez-les ; ils sont exclus du fichier ZIP et de la liste des pièces.",
"Pole zabudowane w płycie USSA (wycięcie na palec) – bez kieszeni.": "Case fermée de la baseplate USSA (encoche pour le doigt) – pas de logement.",
