"3MF: pojemniki tego układu ułożone na płytach drukarki {printer} – jak w „Przygotuj wydruk” (odstęp, projekt slicera, kolory części){plate}.": "3MF : les bacs de cette disposition placés sur les plateaux de l'imprimante {printer} – comme dans « Préparer l'impression » (espacement, projet du slicer, couleurs des pièces){plate}.",
