"Uchwyt górny wchodzi w kratki dachu Grid – wybierz dach Grid.": "La poignée supérieure s'emboîte dans les cases du toit Grid – choisissez le toit Grid.",
"Przeciągnij – obrót, prawy przycisk – przesuwanie, kółko – przybliżenie, kliknięcie frontu – otwarcie, dwuklik – widok domyślny.": "Glisser – pivoter, bouton droit – déplacer, molette – zoom, clic sur une façade – ouvrir, double-clic – vue par défaut.",
