"ilość": "quantité",
"Generuję podgląd…": "Création de l'aperçu…",
"Widok jak we froncie. Wysokość liter: {h} mm. Napis {z} mm nad etykietą – w projekcie Bambu Studio filament zmienia się sam na warstwie od {t} mm (kolor napisu, gdy inny niż kolor etykiety); w innym slicerze zmień go ręcznie.": "Vue comme dans la façade. Hauteur des lettres : {h} mm. Texte à {z} mm au-dessus de l’étiquette – dans un projet Bambu Studio, le filament change tout seul à la couche de {t} mm (couleur du texte, si elle diffère de celle de l’étiquette) ; dans un autre slicer, changez-le à la main.",
"etykiety": "etiquettes",
"STL tej etykiety": "STL de cette étiquette",
"na listę części – zamiast tylu samo pustych etykiet": "dans la liste des pièces – à la place d'autant d'étiquettes vierges",
"Etykieta to plik USSA z Twojej biblioteki (Label albo Label for Sustainers) z wypukłym napisem i symbolem. 3MF: wszystkie etykiety ułożone na płytach drukarki z „Przygotuj wydruk”. Drukuj licem do góry; drugi kolor – zmiana filamentu na wysokości wierzchu etykiety.": "L'étiquette est le fichier USSA de votre bibliothèque (Label ou Label for Sustainers) avec un texte et un symbole en relief. 3MF : toutes les étiquettes placées sur les plateaux de l'imprimante de « Préparer l'impression ». Imprimez face visible vers le haut ; deuxième couleur – changement de filament à la hauteur du dessus de l'étiquette.",
"bez symbolu": "sans symbole",
"szuflada / skrzynka 2F i 4F (Label)": "tiroir / caisson 2F et 4F (Label)",
"skrzynka 1F (Label for Sustainers)": "caisson 1F (Label for Sustainers)",
"litery niższe niż 3 mm – skróć napis albo podziel go na 2 linie": "lettres de moins de 3 mm – raccourcissez le texte ou répartissez-le sur 2 lignes",
"Brak pliku {file} w bibliotece": "Le fichier {file} manque dans la bibliothèque",
"{file}: siatka z błędami – napraw bibliotekę (napraw_stl)": "{file} : maillage avec erreurs – réparez la bibliothèque (repair_stl)",
"styl napisu": "style du texte",
"wypukły – druk licem do góry": "en relief – impression face visible vers le haut",
"wklęsły – druk licem do stołu": "gravé – impression face visible sur le plateau",
"głębokość napisu": "profondeur du texte",
"Widok jak we froncie. Wysokość liter: {h} mm. Napis wycięty na {z} mm w licu; plik leży licem do stołu – gładkie lico i ostre krawędzie liter (jeden kolor).": "Vue comme sur la façade. Hauteur des lettres : {h} mm. Texte gravé de {z} mm dans la face ; le fichier est posé face visible sur le plateau – face lisse et lettres nettes (une couleur).",
"puste etykiety (Label) na liście części": "étiquettes vierges (Label) dans la liste des pièces",
"Wyłącz, jeśli etykiet nie drukujesz albo robisz je w zakładce „Etykiety” (te zostają na liście).": "Désactivez si vous n'imprimez pas d'étiquettes ou si vous les créez dans l'onglet « Étiquettes » (celles-ci restent dans la liste).",
"wpuszczony – drugi filament, druk licem do stołu": "incrusté – deuxième filament, impression face visible sur le plateau",
"grubość napisu": "épaisseur du texte",
"kolor napisu (wspólny dla etykiet)": "couleur du texte (commune aux étiquettes)",
"Widok jak we froncie. Wysokość liter: {h} mm. Dwie części: lico z wyciętym napisem i litery ({z} mm) równo z licem, licem do stołu. W 3MF etykieta to jeden obiekt z dwóch części; w projekcie Bambu Studio litery mają własny filament w kolorze napisu. Pliki STL – dwa na etykietę.": "Vue comme sur la façade. Hauteur des lettres : {h} mm. Deux pièces : la face avec le texte découpé et les lettres ({z} mm) au même niveau, face visible sur le plateau. Dans le 3MF, l'étiquette est un objet en deux pièces ; dans un projet Bambu Studio, les lettres ont leur propre filament dans la couleur du texte. Fichiers STL – deux par étiquette.",
