"Usunięto układ pojemników": "Disposition des bacs supprimée",
"Usunięto etykietę": "Étiquette supprimée",
"Pliki STL do wydrukowania – ilości, czas, filament, licznik wydrukowanych": "Fichiers STL à imprimer – quantités, temps, filament, compteur des pièces imprimées",
"Śruby, pręty, magnesy i inne elementy do kupienia": "Vis, tiges, aimants et autres pièces à acheter",
"Własne pojemniki gridfinity do szuflad i skrzynek (opcjonalnie)": "Bacs gridfinity personnalisés pour tiroirs et caissons (facultatif)",
"Etykiety frontów z napisem i symbolem (opcjonalnie)": "Étiquettes de façade avec texte et symbole (facultatif)",
"Kopie plików STL i gotowe płyty 3MF dla Twojej drukarki": "Copies des STL et plateaux 3MF prêts pour votre imprimante",
"Następny krok:": "Étape suivante :",
"Zwykły – kluczyk z płetwą i nakładką; ukryty – płaski, równy z frontem, z wyjmowanym kluczem.": "Normal – clé à ailette avec capuchon ; cachée – plate, presque au ras de la façade, avec clé amovible.",
"Listwy zębate łączą prowadnice po obu stronach, żeby szuflada nie przekrzywiała się przy wysuwaniu. Zalecane, gdy w module jest kilka szuflad.": "Les rails dentés relient les glissières des deux côtés pour que le tiroir ne se mette pas de travers à l’ouverture. Recommandés quand un module a plusieurs tiroirs.",
"Ile takich samych wież budujesz – lista części mnoży wszystko przez tę liczbę.": "Combien de tours identiques vous construisez – la liste des pièces multiplie tout par ce nombre.",
"Głębokość wszystkich modułów wieży w kratkach gridfinity po 42 mm. Moduł jest o 20 mm dłuższy (np. 4 → 188 mm).": "Profondeur de tous les modules de la tour, en cases gridfinity de 42 mm. Le module fait 20 mm de plus (p. ex. 4 → 188 mm).",
"Wieża rośnie od spodu. Warstwa to jeden poziom: moduł z szufladami albo skrzynka z wiekiem. Wysokość 1F to 48 mm, 2F i 4F – dwa i cztery razy więcej.": "La tour se construit par le bas. Un niveau est un étage : un module à tiroirs ou un caisson avec couvercle. La hauteur 1F fait 48 mm, 2F et 4F deux et quatre fois plus.",
"Podział wysokiego modułu na szuflady – np. 1F / 1F to dwie niskie szuflady w jednym module 2F.": "Répartition d’un module haut en tiroirs – p. ex. 1F / 1F correspond à deux tiroirs bas dans un module 2F.",
"Płaskie – gładkie ściany; pod przegródki – rowki na przegródki poprzeczne i podłużne; szczelne – ścianki dzielące skrzynkę na komory.": "Plat – parois lisses ; séparateurs – rainures pour séparateurs transversaux et longitudinaux ; étanche – parois qui divisent le caisson en compartiments.",
"Grid – kratki gridfinity na wierzchu, Table – płaski blat, Bowl – misa na drobiazgi, Under Table Mount – mocowanie pod blatem, Heavyweight – wzmocniony, z rączką (tylko L i XL).": "Grid – grille gridfinity sur le dessus, Table – plateau plat, Bowl – vide-poche, Under Table Mount – fixation sous un plateau, Heavyweight – renforcé, avec poignée (L et XL uniquement).",
"Podstawa pod wieżę z prętem M16 – do niej montuje się koła i stopkę.": "Socle sous la tour avec tige M16 – les roues et le pied s’y fixent.",
"Listwa z tyłu każdej warstwy, która usztywnia wieżę. Przykręca się do niej pegboard i uchwyt wysuwany. Dedykowany – na szerokość wieży, uniwersalny – dwa klocki przy bokach.": "Barre à l’arrière de chaque niveau qui rigidifie la tour. Le panneau perforé et la poignée télescopique s’y fixent. Dédiée – sur la largeur de la tour, universelle – deux blocs sur les côtés.",
"Uchwyt stały – na tyle wieży; wysuwany – rączka na prętach M16 przez kręgosłup (jak w walizce); ścienne – do zawieszenia warstw na ścianie.": "Poignée fixe – à l’arrière de la tour ; télescopique – poignée sur tiges M16 à travers la colonne (comme une valise) ; fixations murales – pour suspendre les niveaux au mur.",
"Pierwszy raz tutaj?": "Première visite ?",
"Kreator poprowadzi Cię przez 5 kroków: szablon, rozmiar, warstwy od spodu, dach i dodatki – z podglądem i szacunkiem druku. Możesz też od razu edytować „{name}” poniżej.": "L’assistant vous guide en 5 étapes : modèle, taille, niveaux depuis le bas, toit et accessoires – avec aperçu et estimation d’impression. Vous pouvez aussi modifier « {name} » directement ci-dessous.",
"Kreator wieży…": "Assistant de tour…",
"Nie pokazuj": "Ne plus afficher",
