"Rozmiar": "Taille",
"Warstwy": "Niveaux",
"Góra i dodatki": "Dessus et accessoires",
"Podsumowanie": "Récapitulatif",
"Pusta wieża": "Tour vide",
"Jedna warstwa szuflad – resztę dodasz sam.": "Un niveau de tiroirs – vous ajoutez le reste vous-même.",
"Biurko": "Bureau",
"Niska wieża M z szufladami i płaskim blatem.": "Une tour M basse avec tiroirs et plateau plat.",
"Warsztat na kółkach": "Atelier sur roulettes",
"Wysoka wieża L na kołach, z kręgosłupem, rączką i dachem z kratkami.": "Une grande tour L sur roulettes, avec colonne, poignée et toit à grille.",
"Skrzynka narzędziowa": "Caisse à outils",
"Szuflady na dole, na górze skrzynka z wiekiem i przegródkami, uchwyt stały.": "Tiroirs en bas, caisson avec couvercle et séparateurs en haut, poignée fixe.",
"Pod blat": "Sous le plateau",
"Szuflady przykręcane pod blat biurka (dach Under Table Mount).": "Tiroirs vissés sous un plateau de bureau (toit Under Table Mount).",
"Od czego zaczynasz?": "Par quoi commencer ?",
"Wybierz gotowy pomysł i zmień go w kolejnych krokach – albo zacznij od pustej wieży.": "Choisissez une idée toute prête et modifiez-la aux étapes suivantes – ou partez d’une tour vide.",
"Szerokość wieży": "Largeur de la tour",
"wąska – pojedyncze szuflady": "étroite – tiroirs simples",
"średnia": "moyenne",
"szeroka – też 2× S obok siebie": "large – aussi 2× S côte à côte",
"najszersza – tylko warstwy 1F": "la plus large – niveaux 1F uniquement",
"Głębokość": "Profondeur",
"Nazwa i ilość": "Nom et quantité",
"Warstwy od spodu": "Niveaux depuis le bas",
"Każda warstwa stoi na poprzedniej. Szerokość wieży: {W} – wyżej tylko układy tej szerokości.": "Chaque niveau repose sur le précédent. Largeur de la tour : {W} – au-dessus, uniquement des dispositions de cette largeur.",
"Dodaj na górze:": "Ajouter en haut :",
"szuflady {h}F": "tiroirs {h}F",
"skrzynka {h}F": "caisson {h}F",
"Wkłady gridfinity, przegródki skrzynek i podział frontów każdej kolumny ustawisz później w edytorze zestawu.": "Les inserts gridfinity, les séparateurs des caissons et la répartition des façades de chaque colonne se règlent ensuite dans l’éditeur d’ensemble.",
"Po utworzeniu zestaw możesz dalej zmieniać w edytorze: wkłady i pojemniki gridfinity w szufladach, przegródki skrzynek, pegboard. Cofnij (Ctrl+Z) wycofa utworzenie.": "Après la création, vous pouvez continuer à modifier l’ensemble dans l’éditeur : inserts et bacs gridfinity dans les tiroirs, séparateurs des caissons, panneau perforé. Annuler (Ctrl+Z) revient en arrière.",
"Anuluj": "Annuler",
