"Dalej": "Suivant",
"Utwórz (zamiast „{name}”)": "Créer (à la place de « {name} »)",
"Utwórz zestaw": "Créer l’ensemble",
"Kreator wieży": "Assistant de tour",
"Podgląd": "Aperçu",
"Utworzono „{name}”": "« {name} » créé",
"Kreator…": "Assistant…",
"Nowa wieża krok po kroku: szablon, rozmiar, warstwy, góra i dodatki": "Nouvelle tour étape par étape : modèle, taille, niveaux, dessus et accessoires",
"Wyzerowano licznik wydrukowanych części": "Compteur des pièces imprimées remis à zéro",
"Skopiowano pojemniki: {n}": "Bacs copiés : {n}",
"Usunięto wszystkie pojemniki z układu": "Tous les bacs retirés de la disposition",
"Żadna szuflada ani skrzynka w projekcie nie ma jeszcze wkładu gridfinity. Ustaw „Wkład” w szufladzie albo „wkład gridfinity” w skrzynce (edytor zestawu) – każda z nich dostanie tu własny układ pojemników. Poniżej możesz też zaprojektować układ dla szuflady spoza projektu.": "Aucun tiroir ni caisson du projet n’a encore d’insert gridfinity. Choisissez « Insert » dans un tiroir ou « insert gridfinity » dans un caisson (éditeur d’ensemble) – chacun aura ici sa propre disposition de bacs. Ci-dessous, vous pouvez aussi concevoir une disposition pour un tiroir hors projet.",
"Pomoc": "Aide",
"Jak pracować z konfiguratorem": "Comment utiliser le configurateur",
"wskaż folder z plikami STL od USSA.": "indiquez le dossier contenant les fichiers STL d’USSA.",
"Wieża": "Tour",
"kreatorem albo w edytorze zestawu: warstwy od spodu, dach, podstawa i dodatki.": "avec l’assistant ou dans l’éditeur d’ensemble : niveaux depuis le bas, toit, socle et accessoires.",
"Listy części": "Listes de pièces",
"„Do druku” (pliki STL, czas, filament, licznik wydrukowanych) i „Niedrukowane” (śruby, pręty, magnesy).": "« À imprimer » (fichiers STL, temps, filament, compteur) et « Quincaillerie » (vis, tiges, aimants).",
"Opcjonalnie": "En option",
"pojemniki gridfinity do szuflad i skrzynek oraz etykiety frontów z napisem.": "bacs gridfinity pour tiroirs et caissons, et étiquettes de façade avec texte.",
"Wydruk": "Impression",
"kopie STL i płyty 3MF albo projekt slicera dla Twojej drukarki.": "copies STL et plateaux 3MF ou projet de trancheur pour votre imprimante.",
"Skróty klawiszowe": "Raccourcis clavier",
"cofnij / ponów zmianę w projekcie (poza polami tekstowymi)": "annuler / rétablir une modification du projet (hors champs de texte)",
"usuń zaznaczony pojemnik (zakładka pojemników)": "supprimer le bac sélectionné (onglet des bacs)",
"zamknij okno (pomoc, ustawienia, kreator, widok 3D) albo odznacz pojemnik": "fermer une fenêtre (aide, paramètres, assistant, vue 3D) ou désélectionner un bac",
"Widok 3D": "Vue 3D",
"Lewy przycisk – obrót, prawy – przesuwanie, kółko – przybliżenie, dwuklik – widok domyślny, kliknięcie frontu – otwarcie szuflady albo skrzynki. Suwak „Rozsunięcie” rozkłada wieżę na części.": "Bouton gauche – rotation, droit – déplacement, molette – zoom, double-clic – vue par défaut, clic sur une façade – ouvre le tiroir ou le caisson. Le curseur « Éclaté » écarte les pièces de la tour.",
"Projekt zapisuje się sam w tej przeglądarce. „Projekt → Zapisz projekt” zapisuje go do pliku – na kopię albo do przeniesienia na inny komputer. Instrukcje montażu USSA (PDF) są w Ustawieniach, a przy częściach na liście – odnośniki do właściwych stron.": "Le projet s’enregistre tout seul dans ce navigateur. « Projet → Enregistrer le projet » l’écrit dans un fichier – en sauvegarde ou pour le transférer sur un autre ordinateur. Les notices de montage USSA (PDF) sont dans les Paramètres, et les pièces de la liste renvoient aux bonnes pages.",
"„{name}”: uchwyt wysuwany montuje się na kręgosłupie – wybierz kręgosłup.": "« {name} » : la poignée télescopique se fixe sur la colonne – choisissez une colonne.",
"„{name}”: koła i stopka montuje się do podstawy – bez niej są pomijane.": "« {name} » : les roues et le pied se fixent au socle – sans lui, ils sont ignorés.",
"„{name}”: pegboard przykręca się do kręgosłupa – bez niego jest pomijany.": "« {name} » : le panneau perforé se visse sur la colonne – sans elle, il est ignoré.",
"„{name}”, warstwa {n}: skrzynka na pół szerokości pod inną warstwą nie otworzy się na miejscu.": "« {name} », niveau {n} : un caisson demi-largeur sous un autre niveau ne s’ouvrira pas en place.",
"Pojemniki poza siatką płyty: {n} – nie trafiają na listę części (zakładka „Pojemniki gridfinity”).": "Bacs hors de la grille de la plaque : {n} – ils ne figurent pas dans la liste des pièces (onglet « Bacs gridfinity »).",
"Uwagi do projektu: {n}": "Remarques sur le projet : {n}",
"Pokaż": "Afficher",
"Nowy projekt": "Nouveau projet",
"Nowy projekt – poprzedni przywróci „Cofnij”": "Nouveau projet – « Annuler » rétablit le précédent",
"Dodano pojemniki: {n}": "Bacs ajoutés : {n}",
"Wypełnij wolne kratki:": "Remplir les cases libres :",
"Wnętrze": "Intérieur",
"wkład gridfinity we wszystkich szufladach": "insert gridfinity dans tous les tiroirs",
"wkład gridfinity we wszystkich skrzynkach": "insert gridfinity dans tous les caissons",
"Etykiety z projektu": "Étiquettes du projet",
"Po jednej etykiecie na każdy front szuflady i skrzynki w projekcie, z opisem miejsca. Kolejne kliknięcie dopisuje tylko nowe fronty.": "Une étiquette pour chaque façade de tiroir et de caisson du projet, avec son emplacement. Un nouveau clic n’ajoute que les nouvelles façades.",
"Dodano etykiety z projektu: {n}": "Étiquettes ajoutées depuis le projet : {n}",
"Wszystkie fronty projektu mają już etykiety": "Toutes les façades du projet ont déjà une étiquette",
"Puste etykiety USSA są nadal na liście części – fronty, którym nie wpiszesz napisu, dostaną pustą etykietę.": "Les étiquettes vierges USSA sont toujours dans la liste des pièces – les façades sans texte recevront une étiquette vierge.",
"Nie drukuj pustych": "Ne pas imprimer les vierges",
"Wyłączono puste etykiety na liście części": "Étiquettes vierges retirées de la liste des pièces",
"Miejsce: {g}": "Emplacement : {g}",
"Puste etykiety są wyłączone, a liczba etykiet z napisem nie zgadza się z liczbą frontów: {list}.": "Les étiquettes vierges sont désactivées, mais le nombre d’étiquettes avec texte ne correspond pas au nombre de façades : {list}.",
