"Label for Sustainers (skrzynki 1F) {a} z {b}": "Label for Sustainers (caissons 1F) {a} sur {b}",
"Konfigurator VAULT: odmowa dostępu. Adres {host} nie jest dozwolony – dopisz go do zmiennej VAULT_HOSTS (np. VAULT_HOSTS={host}) i uruchom serwer ponownie.": "Configurateur VAULT : accès refusé. L’adresse {host} n’est pas autorisée – ajoutez-la à la variable VAULT_HOSTS (par ex. VAULT_HOSTS={host}) et redémarrez le serveur.",
"Za duże zapytanie.": "Requête trop volumineuse.",
"Za dużo sztuk w zleceniu (najwyżej {n}).": "Trop de pièces dans la tâche (au plus {n}).",
"Starsze wyniki (sprzed wersji 1.1.35) nie mają znacznika, więc zostały – usuń je ręcznie, jeśli nie są potrzebne: {list}": "Les résultats plus anciens (avant la version 1.1.35) n’ont pas de marqueur et ont été conservés – supprimez-les à la main si vous n’en avez pas besoin : {list}",
"Folder na wydruki nie może być korzeniem dysku ani folderem domowym – wybierz podfolder, np. {dir}.": "Le dossier de sortie ne peut pas être la racine d’un disque ni votre dossier personnel – choisissez un sous-dossier, par ex. {dir}.",
