"brak podglądu kształtu": "aperçu de la forme indisponible",
"drukuj klucz (jeden na projekt)": "imprimer la clé (une par projet)",
"Hidden Key Part 2 to wyjmowana rączka do obracania ukrytych zamków – pasuje do wszystkich szuflad, więc wystarczy jedna na projekt.": "Hidden Key Part 2 est une poignée amovible pour tourner les serrures cachées – elle convient à tous les tiroirs, une seule par projet suffit donc.",
