"kroki dla jednej wieży, powtórz {n}×": "étapes pour une tour, à répéter {n}×",
"Kroki od spodu wieży: części i elementy niedrukowane na jedną wieżę, przy częściach strony instrukcji USSA (gdy PDF-y są w bibliotece). Zaznaczone kroki zapisują się z projektem.": "Étapes du bas de la tour vers le haut : pièces et quincaillerie pour une tour, avec les pages du manuel USSA à côté des pièces (si les PDF sont dans la bibliothèque). Les étapes cochées sont enregistrées avec le projet.",
"kroki od spodu wieży z częściami, śrubami i stronami instrukcji USSA.": "étapes depuis le bas de la tour avec pièces, vis et pages du manuel USSA.",
