"_napis": "_texte",
"Uchwyt ścienny przykręca się do tyłu modułów w miejscu kręgosłupa – wybierz kręgosłup „brak”.": "La fixation murale se visse au dos des modules, à la place du backbone – choisissez le backbone « aucun ».",
"„{name}”: uchwyt ścienny przykręca się do tyłu modułów w miejscu kręgosłupa – z kręgosłupem jest pomijany.": "« {name} » : la fixation murale se visse au dos des modules, à la place du backbone – avec un backbone, elle est ignorée.",
"Uchwyt stały przykręca się do kręgosłupa – wybierz kręgosłup.": "La poignée fixe se visse sur le backbone – choisissez un backbone.",
"„{name}”: uchwyt stały przykręca się do kręgosłupa – bez niego jest pomijany.": "« {name} » : la poignée fixe se visse sur le backbone – sans backbone, elle est ignorée.",
"kółka meblowe (Casters Mode)": "roulettes (Casters Mode)",
"Kółka meblowe stoją tam, gdzie koła i stopka – zaznacz podstawę i odznacz koła i stopkę.": "Les roulettes se placent là où vont les roues et les pieds – cochez le socle et décochez les roues et les pieds.",
"Kółko meblowe skrętne z trzpieniem gwintowanym M8": "Roulette pivotante à tige filetée M8",
"kółka meblowe (Casters Mode) – trzpień w otworze Ø 7 mm w spodzie podstawy": "roulettes (Casters Mode) – tige dans le trou Ø 7 mm sous le socle",
"„{name}”: kółka meblowe stoją tam, gdzie koła i stopka – przy kołach albo stopce są pomijane.": "« {name} » : les roulettes se placent là où vont les roues et les pieds – avec roues ou pieds, elles sont ignorées.",
"Pojemniki wyższe niż miejsce w szufladzie albo skrzynce: {n} (zakładka „Pojemniki gridfinity”).": "Bacs plus hauts que l’espace dans le tiroir ou le caisson : {n} (onglet « Bacs gridfinity »).",
