"Kolumna „Płyta”: numery płyt 3MF z ostatniego przygotowania wydruku ({date}).": "Colonne « Plaque » : numéros des plaques 3MF de la dernière préparation d’impression ({date}).",
"Lista części zmieniła się od tamtej pory ({n} poz.) – przygotuj wydruk ponownie.": "La liste des pièces a changé depuis ({n} lignes) – préparez à nouveau l’impression.",
