"szt.": "pcs",
"ilość na płytach różni się od listy – przygotuj wydruk ponownie": "la quantité sur les plaques diffère de la liste – préparez à nouveau l’impression",
"przegródki Grid Dividers": "séparateurs Grid Dividers",
"Płyta gridfinity na dnie pudełka – na niej stoją pojemniki gridfinity (zakładka „Pojemniki gridfinity”); albo przegródki Grid Dividers wsuwane w otwory dna (zakładka „Przegródki”).": "Baseplate gridfinity au fond du corps de tiroir – les bacs gridfinity y reposent (onglet « Bacs gridfinity ») ; ou séparateurs Grid Dividers enfoncés dans les trous du fond (onglet « Séparateurs »).",
"za krótka – najkrótsza przegródka ma {n} odstępów": "trop court – le plus court séparateur couvre {n} pas",
"za długa – najdłuższa przegródka ma {n} odstępów": "trop long – le plus long séparateur couvre {n} pas",
"krzyżuje się z inną przegródką": "croise un autre séparateur",
"nachodzi na inną przegródkę": "chevauche un autre séparateur",
"za blisko równoległej przegródki – stopy nachodzą (odstęp najmniej 3 otwory)": "trop près d’un séparateur parallèle – les pieds se chevauchent (au moins 3 trous d’écart)",
"za blisko ścianki – stopa przegródki na nią wchodzi": "trop près de la paroi – le pied du séparateur la touche",
"Zaprojektuj przegródki Grid Dividers dla tej szuflady ({n} szt.)": "Concevoir les séparateurs Grid Dividers de ce tiroir ({n} pcs)",
"Przegródki Grid Dividers z błędem: {n} – nie trafiają na listę części ({where}).": "Séparateurs Grid Dividers en erreur : {n} – absents de la liste des pièces ({where}).",
"Przegródki szuflad (Grid Dividers)": "Séparateurs de tiroir (Grid Dividers)",
"Żadna szuflada nie ma wkładu „przegródki Grid Dividers”. Ustaw go w edytorze zestawu: Wkład → przegródki Grid Dividers.": "Aucun tiroir n’a l’insert « séparateurs Grid Dividers ». Réglez-le dans l’éditeur d’ensemble : Insert → séparateurs Grid Dividers.",
"Przegródki wsuwa się w otwory w dnie pudełka szuflady (co 10,5 mm) – zamiast płyty gridfinity.": "Les séparateurs s’enfoncent dans les trous du fond du tiroir (tous les 10,5 mm) – à la place d’une baseplate gridfinity.",
"Szuflada:": "Tiroir :",
"{n} przegr.": "{n} sép.",
"Wysokość:": "Hauteur :",
"20 mm – niskie przegródki do każdej szuflady; 34,5 mm – pełna wysokość szuflady 1F; 82,5 mm – pełna wysokość szuflady 2F.": "20 mm – séparateurs bas pour tout tiroir ; 34,5 mm – pleine hauteur d’un tiroir 1F ; 82,5 mm – pleine hauteur d’un tiroir 2F.",
