"Na pół w poprzek": "Couper en deux en largeur",
"Na pół wzdłuż": "Couper en deux en longueur",
"Wyczyszczono przegródki szuflady": "Séparateurs du tiroir effacés",
"skopiuj z…": "copier depuis…",
"brak pliku w bibliotece": "fichier absent de la bibliothèque",
"Przegródka {k}: {err}": "Séparateur {k} : {err}",
"Części dla tej szuflady (× {n}):": "Pièces pour ce tiroir (× {n}) :",
"Brak przegródek.": "Aucun séparateur.",
"Długości jak w plikach USSA: liczba w nazwie to liczba odstępów 10,5 mm. Przy ściance – przegródka i część brzegowa (szczelnie), przy innej przegródce – sama przegródka.": "Longueurs comme dans les fichiers USSA : le nombre dans le nom est le nombre de pas de 10,5 mm. Contre une paroi – séparateur et pièce de bordure (étanche) ; contre un autre séparateur – séparateur seul.",
"Usunięto przegródkę": "Séparateur supprimé",
"część brzegowa": "pièce de bordure",
"zakończenie zaokrąglone": "embout arrondi",
"przegródka {n}": "séparateur {n}",
"Przegródki Grid Dividers": "Séparateurs Grid Dividers",
"Przegródki Grid Dividers w otworach dna szuflad (opcjonalnie)": "Séparateurs Grid Dividers dans les trous du fond des tiroirs (facultatif)",
"przegródka Grid Dividers {n} ({h} mm)": "séparateur Grid Dividers {n} ({h} mm)",
"część brzegowa przegródki ({h} mm)": "pièce de bordure de séparateur ({h} mm)",
"zakończenie zaokrąglone przegródki ({h} mm)": "embout arrondi de séparateur ({h} mm)",
"pin przegródki": "goupille de séparateur",
"generuje konfigurator (zakładka „Przegródki”)": "généré par le configurateur (onglet « Séparateurs »)",
"łuk wychodzi poza pudełko – stopa wchodzi na ściankę": "l’arc sort du corps – son pied touche la paroi",
"koniec łuku za blisko ścianki – nie ma miejsca na język": "extrémité de l’arc trop près de la paroi – pas de place pour la languette",
"łuk przegródki {kat}°, promień {r} mm ({h} mm)": "arc de séparateur {kat}°, rayon {r} mm ({h} mm)",
"Rysuj:": "Dessiner :",
"Łuk: kliknij otwór w środku łuku i przeciągnij w stronę, w którą ma się wyginać. Końce łuku leżą w otworach – dociągnij do nich przegródki.": "Arc : cliquez sur le trou au centre de l’arc et faites glisser vers le côté où il doit se courber. Les extrémités de l’arc tombent dans des trous – tracez les séparateurs jusqu’à elles.",
"przegródkę": "séparateur",
"łuk 90°": "arc 90°",
"łuk 180° (zawrót)": "arc 180° (demi-tour)",
"Promień:": "Rayon :",
"Promień łuku w odstępach siatki (10,5 mm), mierzony do osi przegródki.": "Rayon de l’arc en pas de grille (10,5 mm), mesuré jusqu’à l’axe du séparateur.",
"Łuk {k}: {err}": "Arc {k} : {err}",
"łuk {kat}°, promień {r} odstępów": "arc {kat}°, rayon {r} pas",
"różne": "différents",
