"Słupki generuje serwer konfiguratora (wersja generatora {v}) – uruchom konfigurator ponownie po aktualizacji.": "Les plots sont générés par le serveur du configurateur (version du générateur {v}) – redémarrez le configurateur après la mise à jour.",
